def similar_shelf_codes(codes, target):
    res = set()
    for c in codes:
        if c >= 0:
            diff = c ^ target
            if diff > 0 and (diff & (diff - 1)) == 0:
                res.add(c)
    return sorted(res, reverse=True)

def min_sensor_pair_or(flags):
    u = list(set(flags))
    if len(u) < 2:
        return None
    return min(u[i] | u[j] for i in range(len(u)) for j in range(i + 1, len(u)))

def densest_ticket_price(prices):
    if not prices:
        return 0
    return min(prices, key=lambda x: (-bin(x).count('1'), x))

def rotate_valve_byte(state, k):
    k %= 8
    return ((state << k) | (state >> (8 - k))) & 0xFF

def xor_even_beacons(signals):
    res = 0
    for s in signals[::2]:
        res ^= s
    return res

def highest_common_channel(masks):
    if not masks:
        return -1
    common = masks[0]
    for m in masks[1:]:
        common &= m
    return common.bit_length() - 1 if common > 0 else -1

def count_close_readings(readings, k):
    if k < 0:
        return 0
    n = len(readings)
    return sum(1 for i in range(n) for j in range(i + 1, n) if abs(readings[i] - readings[j]) <= k)

def generate_shelf_labels(chars):
    n = len(chars)
    labels = {chars[i] + chars[j] for i in range(n) for j in range(i + 1, n)}
    return sorted(labels)

def count_playlist_trios(lengths, target):
    n = len(lengths)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if lengths[i] + lengths[j] + lengths[k] == target:
                    count += 1
    return count

def valid_seat_maps(n, k):
    if n <= 0:
        return 1 if n == 0 and k <= 0 else 0
    count = 0
    for i in range(1 << n):
        s = bin(i)[2:].zfill(n)
        if '11' not in s and s.count('0') >= k:
            count += 1
    return count

def subset_package_weights(weights):
    if not weights:
        return ()
    totals = set()
    for i in range(1, 1 << len(weights)):
        totals.add(sum(weights[j] for j in range(len(weights)) if (i >> j) & 1))
    return tuple(sorted(totals, reverse=True))

def count_ticket_codes(digits):
    n = len(digits)
    codes = set()
    for i in range(n):
        if digits[i] == 0:
            continue
        for j in range(n):
            for k in range(n):
                if i != j and j != k and i != k:
                    codes.add((digits[i], digits[j], digits[k]))
    return len(codes)

def count_equal_splits(crates):
    n = len(crates)
    return sum(1 for i in range(1, n) if sum(crates[:i]) == sum(crates[i:]))

def pouch_coin_sums(pouches):
