        return []
    sums = {0}
    for p in pouches:
        sums = {s + c for s in sums for c in p}
    return sorted(sums)

def count_rising_signals(signals, k):
    if k <= 0 or k > len(signals):
        return 0
    if k == 1:
        return len(signals)
    return sum(count_rising_signals([s for s in signals[i+1:] if s > signals[i]], k - 1) for i in range(len(signals)))

def closest_warehouse_post(posts):
    if not posts:
        return None
    return min(posts, key=lambda p: (abs(p[0]) + abs(p[1]), p[0], p[1]))

def window_overlap_area(w1, w2):
    x_left = max(min(w1[0], w1[2]), min(w2[0], w2[2]))
    y_bottom = max(min(w1[1], w1[3]), min(w2[1], w2[3]))
    x_right = min(max(w1[0], w1[2]), max(w2[0], w2[2]))
    y_top = min(max(w1[1], w1[3]), max(w2[1], w2[3]))
    return max(0, x_right - x_left) * max(0, y_top - y_bottom)

