    return (min(p[0] for p in valid), min(p[1] for p in valid), max(p[2] for p in valid), max(p[3] for p in valid))

def watered_orchard_trees(trees, center, r):
    if r <= 0:
        return 0
    cx, cy = center
    return len({(x, y) for x, y in trees if (x - cx) ** 2 + (y - cy) ** 2 < r * r})

def seats_at_manhattan_ring(r0, c0, d):
    if d < 0:
        return []
    if d == 0:
        return [(r0, c0)]
    pts = set()
    for dr in range(-d, d + 1):
        rem = d - abs(dr)
        pts.add((r0 + dr, c0 - rem))
        pts.add((r0 + dr, c0 + rem))
    return sorted(pts)

def count_laser_left_turns(path):
    pts = [p for i, p in enumerate(path) if i == 0 or p != path[i - 1]]
    turns = 0
    for i in range(len(pts) - 2):
        a, b, c = pts[i], pts[i + 1], pts[i + 2]
        if (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0]) > 0:
            turns += 1
    return turns

