def isolated_room_numbers(rooms, k):
    uniques = sorted(set(rooms))
    result = []
    for i, r in enumerate(uniques):
        left_ok = (i == 0) or (r - uniques[i - 1] >= k)
        right_ok = (i == len(uniques) - 1) or (uniques[i + 1] - r >= k)
        if left_ok and right_ok:
            result.append(r)
    return result

def partition_weights_by_frequency_parity(weights):
