def most_frequent_shelf_digit(labels):
    digits = [int(ch) for label in labels for ch in label if ch.isdigit()]
    if not digits:
        return None
    counts = {d: digits.count(d) for d in set(digits)}
    return min(counts, key=lambda d: (-counts[d], d))

def avg_ticket_segment_length(code):
