def pack_shelf_books(weights, limit):
    indexed = sorted(enumerate(weights), key=lambda x: (x[1], x[0]))
    chosen = []
    total = 0
    for idx, w in indexed:
        if total + w <= limit:
            chosen.append((idx, w))
            total += w
    chosen.sort(key=lambda x: x[0])
    return tuple(w for _, w in chosen)

def count_unpaired_seats(requests, k):
    reqs = sorted(requests)
    i = 0
    paired = 0
    while i < len(reqs) - 1:
        if reqs[i + 1] - reqs[i] <= k:
            paired += 2
            i += 2
        else:
            i += 1
    return len(reqs) - paired

