def count_ribbon_cuts(n, f):
    if n <= 0:
        return 0
    dp = [1] + [0] * n
    for i in range(1, n + 1):
        dp[i] = sum(dp[i - p] for p in range(1, i + 1) if p != f)
    return dp[n]

