        return None
    counts = [0, 0]
    for c in coins:
        counts[c % 2] += 1
    return min(coins, key=lambda c: (-(counts[c % 2] - 1), c))

from math import gcd

def negative_product_ratio(crates):
    n = len(crates)
    if n < 2:
        return (0, 1)
    pos = sum(1 for x in crates if x > 0)
    neg = sum(1 for x in crates if x < 0)
    fav = pos * neg
    tot = n * (n - 1) // 2
    g = gcd(fav, tot)
    return (fav // g, tot // g)

