    for b in log:
        counts[b] = counts.get(b, 0) + 1
    return tuple(b for b, c in counts.items() if c == k)

def rounded_cafe_averages(reviews):
    sums, counts = {}, {}
    for cafe, score in reviews:
        sums[cafe] = sums.get(cafe, 0) + score
        counts[cafe] = counts.get(cafe, 0) + 1
    res = {}
    for cafe, total in sums.items():
        avg = total / counts[cafe]
        res[cafe] = int(avg + 0.5) if avg >= 0 else int(avg - 0.5)
    return res

def count_long_rare_words(sentence):
    words = sentence.split()
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return sum(1 for w, c in counts.items() if len(w) > c)

def unique_peak_room(readings):
    if not readings:
        return None
    totals = {}
    for room, watts in readings:
        totals[room] = totals.get(room, 0) + watts
    top = max(totals.values())
    winners = [r for r, w in totals.items() if w == top]
    return winners[0] if len(winners) == 1 else None

def most_frequent_shelf_segment(labels):
