def parcel_digit_count_spread(parcel_ids):
    if not parcel_ids:
        return 0
    counts = [sum(ch.isdigit() for ch in pid) for pid in parcel_ids]
    return max(counts) - min(counts)

def telegram_unique_length_counts(telegram):
    words = set(w.lower() for w in telegram.split() if w)
    counts = {}
    for w in words:
        counts[len(w)] = counts.get(len(w), 0) + 1
    return dict(sorted(counts.items()))

def active_aisle_letters(labels):
    res = set()
    for part in labels.split():
        if ':' in part:
            aisle, num = part.split(':', 1)
            if int(num) > 0:
                res.add(aisle)
    return tuple(sorted(res))

def sum_sensor_log(log):
    nums = [int(x.strip()) for x in log.split(',') if x.strip()]
