        return ''
    totals = {}
    for t in tickets:
        p, c = t.rsplit('-', 1)
        totals[p] = totals.get(p, 0) + int(c)
    return min(totals, key=lambda k: (-totals[k], k))

def average_track_seconds(playlist):
    tracks = [t.strip() for t in playlist.split(';') if t.strip()]
    if not tracks:
        return 0.0
    total = sum(int(t.split(':')[0]) * 60 + int(t.split(':')[1]) for t in tracks)
    return float(total) / len(tracks)

def unblocked_seat_rows(seat_map):
    if not seat_map:
        return []
    rows = seat_map.split('\n')
    return [i + 1 for i, r in enumerate(rows) if '.' in r and '#' not in r]

def extract_clean_hashtags(post):
    seen = []
    for w in post.split():
        if w.startswith('#'):
            tag = w[1:].rstrip('.,!?').lower()
            if tag and tag not in seen:
                seen.append(tag)
    return seen

def parse_first_config(cfg):
    res = {}
    for part in cfg.split('/'):
        if '=' in part:
            k, v = part.split('=', 1)
            if k and k not in res:
                try:
                    res[k] = int(v)
                except ValueError:
                    pass
    return res

def compress_long_runs(s):
    if not s:
        return ''
    res, cur, cnt = [], s[0], 0
    for ch in s:
        if ch == cur:
            cnt += 1
        else:
            res.append(f'{cur}{cnt}' if cnt >= 3 else cur * cnt)
            cur, cnt = ch, 1
    res.append(f'{cur}{cnt}' if cnt >= 3 else cur * cnt)
    return ''.join(res)

def ledger_balance_stats(entries):
    bal = 0
    min_bal = 0
    for token in entries.split():
        bal += int(token)
        if bal < min_bal:
            min_bal = bal
    return (bal, min_bal)

def pack_shelf_box(weights, c):
    indexed = sorted(enumerate(weights), key=lambda x: (x[1], x[0]))
    chosen = []
    for idx, w in indexed:
        if w <= c:
            c -= w
            chosen.append((idx, w))
    chosen.sort(key=lambda x: x[0])
    return [w for _, w in chosen]

def redeem_coupons(coupons, target):
    if target <= 0:
        return ()
    pos = sorted((x for x in coupons if x > 0), reverse=True)
    chosen = []
    for x in pos:
        chosen.append(x)
        target -= x
        if target <= 0:
            return tuple(chosen)
    return None

def filter_sensor_spikes(readings, delta):
    if not readings:
        return []
    kept = [readings[0]]
    for r in readings[1:]:
        if abs(r - kept[-1]) >= delta:
            kept.append(r)
    return kept

def unassigned_ticket_count(requests, capacities):
    reqs = sorted(requests)
    caps = sorted(capacities)
    i = j = matched = 0
    while i < len(reqs) and j < len(caps):
        if caps[j] >= reqs[i]:
            matched += 1
            i += 1
        j += 1
    return len(reqs) - matched

def max_unique_playlist(songs, k):
    if k <= 0:
        return 0
    best = {}
    for artist, dur in songs:
        if dur > max(0, best.get(artist, 0)):
            best[artist] = dur
    top = sorted(best.values(), reverse=True)[:k]
    return int(sum(top))

def batch_log_files(sizes, limit):
    batches, cur, total = [], [], 0
    for s in sizes:
        if s > limit:
            continue
        if cur and total + s > limit:
            batches.append(cur)
            cur, total = [s], s
        else:
            cur.append(s)
            total += s
    return batches + ([cur] if cur else [])

def pair_drone_batteries(batteries, max_load):
    b = sorted(batteries)
    i, j = 0, len(b) - 1
    pairs = []
    while i < j:
        if b[i] + b[j] <= max_load:
            pairs.append((b[i], b[j]))
            i += 1
        j -= 1
    return pairs

def schedule_guard_shifts(shifts):
    valid = [s for s in shifts if s[0] < s[1]]
    valid.sort(key=lambda x: (x[1], -x[0]))
    res = []
    last_end = float('-inf')
    for s, e in valid:
        if s >= last_end:
            res.append((s, e))
            last_end = e
    return res

def buy_cheapest_crates(offers, need):
    if need <= 0:
        return 0.0
    total = 0.0
    for cost, qty in sorted(offers, key=lambda x: x[0]):
        if qty > 0:
            take = min(need, qty)
            total += take * cost
            need -= take
            if need == 0:
                return float(total)
    return -1.0

def greedy_stepping_stones(stones):
    if not stones:
        return []
    path, i, n = [0], 0, len(stones)
    while i < n - 1:
        if stones[i] <= 0:
            return []
        i = min(n - 1, i + stones[i])
        path.append(i)
    return path

def greenhouse_cycle_pos(day_index, length):
    if length <= 0:
        return None
    q, r = divmod(day_index, length)
    return (q + 1, r + 1)

def count_beacon_flashes(start_day, end_day, period):
    if start_day > end_day or period == 0:
        return 0
    p = abs(period)
    return (end_day // p) - ((start_day - 1) // p)

def rover_uplink_days(total_days, schedules):
    if total_days <= 0:
        return []
    days = set()
    for offset, step in schedules:
        if step > 0:
            start = offset % step if offset < 0 else offset
            if start < total_days:
                days.update(range(start, total_days, step))
    return sorted(days)

def almanac_month_day(day_of_year, month_lengths):
    if day_of_year < 1 or not month_lengths:
        return None
    rem = day_of_year
    for i, length in enumerate(month_lengths, 1):
        if rem <= length:
            return (i, rem)
        rem -= length
    return None

def covered_workdays(start, duration, w):
    if duration <= 0 or w <= 0:
        return []
    if duration >= w:
        return list(range(w))
    return sorted({(start + i) % w for i in range(duration)})

def longest_tide_streak(days):
    if not days:
        return (None, 0)
    s = sorted(set(days))
    best_start = cur_start = s[0]
    best_len = cur_len = 1
    for prev, curr in zip(s, s[1:]):
        if curr == prev + 1:
            cur_len += 1
        else:
            cur_start, cur_len = curr, 1
        if cur_len > best_len:
            best_start, best_len = cur_start, cur_len
    return (best_start, best_len)

def advance_kiln_workdays(start_day, steps, holidays):
    h = set(holidays)
    curr = start_day
    while curr in h:
        curr += 1
    for _ in range(steps):
        curr += 1
        while curr in h:
            curr += 1
    return curr

def lease_overlap_days(a_start, a_end, b_start, b_end):
    if a_start > a_end or b_start > b_end:
        return 0
    start = max(a_start, b_start)
    end = min(a_end, b_end)
    return max(0, end - start + 1)

def quarry_roster_pay(start_day, end_day, weekday_rate, weekend_rate):
    if start_day > end_day:
        return 0
    total_days = end_day - start_day + 1
    full_weeks, rem = divmod(total_days, 7)
    pay = full_weeks * (5 * weekday_rate + 2 * weekend_rate)
    for i in range(rem):
        pay += weekday_rate if (start_day + i) % 7 < 5 else weekend_rate
    return pay

def pierced_shelves(x0, shelves):
    res = set()
    for x1, x2, y in shelves:
        if min(x1, x2) < x0 < max(x1, x2):
            res.add(y)
    return sorted(res)

def closest_first_quadrant_post(posts):
    valid = [(x, y) for x, y in posts if x > 0 and y > 0]
    if not valid:
        return None
    return min(valid, key=lambda p: (p[0]**2 + p[1]**2, p[0]))

def seat_cover_area(seats):
    if not seats:
        return 0
    xs = [x for x, y in seats]
    ys = [y for x, y in seats]
    return (max(xs) - min(xs)) * (max(ys) - min(ys))

import math
def count_segment_waypoints(x1, y1, x2, y2):
    return math.gcd(abs(x2 - x1), abs(y2 - y1)) + 1

def beacons_in_range(cx, cy, r, beacons):
    if r < 0:
        return ()
    valid = {(x, y) for x, y in beacons if (x - cx)**2 + (y - cy)**2 <= r**2}
    return tuple(sorted(valid))

def count_left_turns(path):
    pts = [p for i, p in enumerate(path) if i == 0 or p != path[i - 1]]
    turns = 0
    for i in range(len(pts) - 2):
        dx1, dy1 = pts[i+1][0] - pts[i][0], pts[i+1][1] - pts[i][1]
        dx2, dy2 = pts[i+2][0] - pts[i+1][0], pts[i+2][1] - pts[i+1][1]
        if dx1 * dx2 + dy1 * dy2 == 0 and dx1 * dy2 - dy1 * dx2 > 0:
            turns += 1
    return turns

def integer_midpoint(p1, p2):
    if (p1[0] + p2[0]) % 2 == 0 and (p1[1] + p2[1]) % 2 == 0:
        return ((p1[0] + p2[0]) // 2, (p1[1] + p2[1]) // 2)
    return None

def double_monitored_points(ranges):
    counts = {}
    for x1, x2 in ranges:
        for x in range(min(x1, x2), max(x1, x2) + 1):
            counts[x] = counts.get(x, 0) + 1
    return sorted(x for x, c in counts.items() if c >= 2)

def one_bit_shelf_codes(codes, target):
    res = set()
    for c in codes:
        d = c ^ target
        if d > 0 and (d & (d - 1)) == 0:
            res.add(c)
    return tuple(sorted(res))

def tightest_ticket_id(tickets):
    if not tickets:
        return None
    def key(t):
        low = (t & -t).bit_length() - 1
        high = t.bit_length() - 1
        return (high - low, -t)
    return min(tickets, key=key)

def rotate_seat_masks(rows, k):
    k %= 6
    res = [((r << k) | (r >> (6 - k))) & 0x3F for r in rows]
    return sorted(res, reverse=True)

def group_valves_by_lsb(states):
    res = {}
    for s in sorted(states):
        lsb = s & -s
        res.setdefault(lsb, []).append(s)
    return res

def count_disjoint_mask_pairs(masks):
    n = len(masks)
    return sum(1 for i in range(n) for j in range(i + 1, n) if (masks[i] & masks[j]) == 0)

def invert_beacon_signals(signals):
    res = {s ^ ((1 << s.bit_length()) - 1) for s in signals}
    return sorted(res)

def aligned_shelf_labels(grid):
    if len(grid) < 2 or not grid[0]:
        return []
    found = set()
    for r in range(len(grid) - 1):
        for c in range(len(grid[0])):
            if grid[r][c] == grid[r + 1][c]:
                found.add(grid[r][c])
    return sorted(found)

def best_border_seat(cabin):
    if not cabin or not cabin[0]:
        return None
    R, C = len(cabin), len(cabin[0])
    best_val, best_pos = None, None
    for r in range(R):
        for c in range(C):
            if r == 0 or r == R - 1 or c == 0 or c == C - 1:
                if best_val is None or cabin[r][c] > best_val:
                    best_val, best_pos = cabin[r][c], (r, c)
    return best_pos

def lowest_drift_column(readings):
    if not readings or not readings[0]:
        return None
    cols = [sum(row[c] for row in readings) for c in range(len(readings[0]))]
    best_col = 0
    for c in range(1, len(cols)):
        if cols[c] <= cols[best_col]:
            best_col = c
    return best_col

def count_peak_booths(queues):
    count = 0
    for row in queues:
        for c, val in enumerate(row):
            left = row[c - 1] if c > 0 else float('-inf')
            right = row[c + 1] if c + 1 < len(row) else float('-inf')
            if val > left and val > right:
                count += 1
    return count

def even_diagonal_pixels(image):
    if not image or not image[0]:
        return ()
    limit = min(len(image), len(image[0]))
    return tuple(image[i][i] for i in range(limit) if image[i][i] >= 0 and image[i][i] % 2 == 0)

def staggered_timetable_flat(grid):
    res = []
    for r, row in enumerate(grid):
        if row:
            k = r % len(row)
            res.extend(row[-k:] + row[:-k] if k else row)
    return res

def valid_crate_rows(weights):
    res = []
    for row in weights:
        if sum(row) > 0 and all(row[i] < row[i + 1] for i in range(len(row) - 1)):
            res.append(list(row))
    return res

def internal_terrain_average(terrain):
    if len(terrain) < 3 or len(terrain[0]) < 3:
        return None
    vals = [row[c] for row in terrain[1:-1] for c in range(1, len(row) - 1)]
    return float(sum(vals) / len(vals))

def repeated_row_tracks(playlists):
    repeated = set()
    for row in playlists:
        seen = set()
        for length in row:
            if length in seen:
                repeated.add(length)
            seen.add(length)
    return sorted(repeated)

def select_playlist_durations(durations, target):
    if target <= 0:
        return []
    picked, total = [], 0
    for d in sorted((x for x in durations if x > 0), reverse=True):
        picked.append(d)
        total += d
        if total >= target:
            return picked
    return None

def pair_sensor_readings(readings, tolerance):
    res, i = [], 0
    while i < len(readings) - 1:
        if abs(readings[i] - readings[i + 1]) <= tolerance:
            res.append((readings[i], readings[i + 1]))
            i += 2
        else:
            i += 1
    return res

def filter_cooldown_timestamps(timestamps, gap):
    kept = []
    for t in timestamps:
        if not kept or t - kept[-1] >= gap:
            kept.append(t)
    return tuple(kept)

def assign_crates_to_trucks(crates, trucks):
    crates_s = sorted(crates)
    trucks_s = sorted(trucks)
    i = j = 0
    while i < len(crates_s) and j < len(trucks_s):
        if trucks_s[j] >= crates_s[i]:
            i += 1
        j += 1
    return i

def collect_positive_badges(badges):
    score, count = 0, 0
    for b in badges:
        if score + b > 0:
            score += b
            count += 1
        else:
            break
    return (count, score)

def allocate_theater_rows(rows, groups):
    rem = list(rows)
    for g in groups:
        if g <= 0:
            continue
        for i in range(len(rem)):
            if rem[i] >= g:
                rem[i] -= g
                break
    return rem

def top_unique_vouchers(vouchers, k):
    if k <= 0:
        return []
    seen, picked = set(), []
    for code, val in sorted(vouchers, key=lambda x: x[1], reverse=True):
        if code not in seen:
            seen.add(code)
            picked.append(val)
            if len(picked) == k:
                break
    return picked

def closest_beacon(rx, ry, beacons):
    unique_b = set(beacons)
    if not unique_b:
        return None
    dists = [((x - rx)**2 + (y - ry)**2, (x, y)) for x, y in unique_b]
    dists.sort()
    if len(dists) > 1 and dists[0][0] == dists[1][0]:
        return None
    return dists[0][1]

def marker_triangle_areas(markers):
    pts = list(set(markers))
    areas = set()
    for i in range(len(pts)):
        for j in range(i + 1, len(pts)):
            double_area = abs(pts[i][0] * pts[j][1] - pts[i][1] * pts[j][0])
            if double_area > 0 and double_area % 2 == 0:
                areas.add(double_area // 2)
    return sorted(areas)

def count_right_turns(waypoints):
    pts = [w for i, w in enumerate(waypoints) if i == 0 or w != waypoints[i - 1]]
    turns = 0
    for i in range(len(pts) - 2):
        dx1, dy1 = pts[i+1][0] - pts[i][0], pts[i+1][1] - pts[i][1]
        dx2, dy2 = pts[i+2][0] - pts[i+1][0], pts[i+2][1] - pts[i+1][1]
        if dx1 * dx2 + dy1 * dy2 == 0 and dx1 * dy2 - dy1 * dx2 < 0:
            turns += 1
    return turns

def rank_seats(seats):
    unique_seats = set(seats)
    return sorted(unique_seats, key=lambda s: (abs(s[0]) + abs(s[1]), s[0], s[1]))

import math
def max_trees_in_sight(fx, fy, trees):
    dirs = {}
    for x, y in set(trees):
        dx, dy = x - fx, y - fy
        if dx != 0 or dy != 0:
            g = math.gcd(dx, dy)
            d = (dx // g, dy // g)
            dirs[d] = dirs.get(d, 0) + 1
    return max(dirs.values(), default=0)

def towers_in_zone(cx, cy, r, towers):
    if r <= 0:
        return []
    r2 = r * r
    valid = {(x, y) for x, y in towers if (x - cx)**2 + (y - cy)**2 < r2}
    return sorted(valid)

def is_square_pen(posts):
    pts = list(set(posts))
    if len(pts) != 4:
        return False
    d = sorted((pts[i][0] - pts[j][0])**2 + (pts[i][1] - pts[j][1])**2 for i in range(4) for j in range(i + 1, 4))
    return d[0] > 0 and d[0] == d[1] == d[2] == d[3] and d[4] == d[5] == 2 * d[0]

def active_wifi_sensors(sensors, cx, cy, r):
    if r <= 0:
        return []
    r2 = r * r
    valid = { (x, y) for x, y in sensors if (x - cx) ** 2 + (y - cy) ** 2 < r2 }
    return sorted(valid)

def min_shipping_box(points):
    unique = set(points)
    if len(unique) < 2:
        return None
    xs = [p[0] for p in unique]
    ys = [p[1] for p in unique]
    return (max(xs) - min(xs)) * (max(ys) - min(ys))

import math
def count_laser_beams(targets):
    rays = set()
    for x, y in targets:
        if x == 0 and y == 0:
            continue
        g = math.gcd(x, y)
        rays.add((x // g, y // g))
    return len(rays)

def closest_theatre_seat(seats):
    if not seats:
        return None
    return min(seats, key=lambda s: (abs(s[0]) + abs(s[1]), s[0], s[1]))

def is_straight_fence(posts):
    pts = [p for i, p in enumerate(posts) if i == 0 or p != posts[i - 1]]
    if len(set(pts)) < 2:
        return False
    x0, y0 = pts[0]
    x1, y1 = next(p for p in pts if p != (x0, y0))
    return all((x - x0) * (y1 - y0) == (y - y0) * (x1 - x0) for x, y in pts)

def double_garden_area(p1, p2, p3):
    val = abs(p1[0] * (p2[1] - p3[1]) + p2[0] * (p3[1] - p1[1]) + p3[0] * (p1[1] - p2[1]))
    return val if val > 0 else None

def navigate_warehouse_robot(commands):
    x, y, dx, dy = 0, 0, 0, 1
    for cmd in commands:
        if cmd == 'L':
            dx, dy = -dy, dx
        elif cmd == 'R':
            dx, dy = dy, -dx
        elif isinstance(cmd, int):
            x, y = x + dx * cmd, y + dy * cmd
    return (x, y)

def select_playlist_tracks(durations, capacity):
    indexed = sorted(enumerate(durations), key=lambda x: (x[1], x[0]))
    chosen = []
    for idx, d in indexed:
        if capacity < d:
            break
        capacity -= d
        chosen.append((idx, d))
    return [d for idx, d in sorted(chosen)]

def count_solo_parcels(weights, limit):
    w = sorted(weights)
    i, j = 0, len(w) - 1
    solos = 0
    while i <= j:
        if i == j:
            solos += 1
            break
        if w[i] + w[j] <= limit:
            i += 1
            j -= 1
        else:
            solos += 1
            j -= 1
    return solos

def boost_sensor_offsets(offsets, k):
    negs = sorted(x for x in offsets if x < 0)[:max(0, k)]
    return (sum(offsets) - 2 * sum(negs), len(negs))

def place_shelf_dividers(widths, shelf_size):
    dividers = 0
    rem = shelf_size
    for w in widths:
        if w > rem:
            dividers += 1
            rem = shelf_size - w
        else:
            rem -= w
    return dividers

def assign_freelance_tasks(payouts, rates):
    if not rates:
        return None
    p = sorted((x for x in payouts if x > 0), reverse=True)
    r = sorted((x for x in rates if x > 0), reverse=True)
    return float(sum(x * y for x, y in zip(p, r)))

def filter_ticket_codes(codes, step):
    kept = []
    for c in codes:
        if not kept or (c > kept[-1] and c >= kept[-1] + step):
            kept.append(c)
    return kept

def redeem_bill_vouchers(vouchers, bill):
    used = []
    for v in sorted(vouchers, reverse=True):
        if 0 <= v <= bill:
            bill -= v
            used.append(v)
    return sorted(used)

def board_commuter_shuttles(commuters, shuttles):
    rem = list(shuttles)
    for c in commuters:
        candidates = [(cap, idx) for idx, cap in enumerate(rem) if cap >= c]
        if candidates:
            _, best_idx = min(candidates)
            rem[best_idx] -= c
    return tuple(rem)

def closest_to_zero_sensor(readings):
    if not readings:
        return None
    best_id, best_temp = readings[0]
    for s_id, temp in readings[1:]:
        if abs(temp) <= abs(best_temp):
            best_id, best_temp = s_id, temp
    return best_id

def sum_first_positive_prices(tags):
    seen = set()
    total = 0
    for aisle, item, price in tags:
        if price > 0 and (aisle, item) not in seen:
            seen.add((aisle, item))
            total += price
    return total

def compact_crate_weights(crates):
    grouped = []
    for cid, w in crates:
        if grouped and grouped[-1][0] == cid:
            grouped[-1][1] += w
        else:
            grouped.append([cid, w])
    return [(cid, w) for cid, w in grouped if w > 0]

def net_altitude_change(checkpoints):
    if len(checkpoints) < 2:
        return 0
    ordered = sorted(checkpoints, key=lambda x: x[0])
    return ordered[-1][1] - ordered[0][1]

def unique_rail_corridors(tickets):
    corridors = set()
    for a, b in tickets:
        if a != b:
            corridors.add((min(a, b), max(a, b)))
    return sorted(corridors)

def top_student_scores(records):
    best = {}
    for name, score in records:
        if name not in best or score > best[name]:
            best[name] = score
    return tuple(sorted(best.items(), key=lambda x: (-x[1], x[0])))

def shift_work_windows(windows, offset):
    res = []
    for s, e in windows:
        if e > s:
            res.append((max(0, s + offset), e + offset))
    return res

def bulk_invoice_total(lines):
    total = 0
    for _, qty, price in lines:
        cost = qty * price
        if qty >= 10:
            cost //= 2
        total += cost
    return total

def sort_seat_codes(seats):
    def key(s):
        row, col = int(s[:-1]), s[-1]
        return (row, col not in ('A', 'F'), col)
    return sorted(seats, key=key)

def rank_discounted_items(items):
    def key(item):
        name, price, disc = item
        return (price * (100 - disc), -disc)
    return [name for name, _, _ in sorted(items, key=key)]

def sort_ingredients_by_weight(ingredients):
    def key(s):
        parts = s.rsplit(' ', 1)
        if len(parts) == 2 and parts[1].endswith('g') and parts[1][:-1].isdigit():
            return (0, int(parts[1][:-1]))
        return (1, 0)
    return sorted(ingredients, key=key)

def sort_versions_desc(versions):
    def key(v):
        parts = [int(x) for x in v.split('.')]
        major, minor = (parts[0], parts[1]) if len(parts) > 1 else (parts[0], 0)
        return (-major, -minor, len(v))
    return sorted(versions, key=key)

def sensor_pair_xor(readings):
    if len(readings) < 2:
        return None
    inv = [r ^ 0xf for r in readings]
    return [inv[i] ^ inv[i + 1] for i in range(len(inv) - 1)]

def common_highest_seat_bit(maps):
    valid = [m for m in maps if m >= 0]
    if not valid:
        return -1
    common = valid[0]
    for m in valid[1:]:
        common &= m
    return common.bit_length() - 1 if common > 0 else -1

def closest_beacon_id(beacons, target):
    if not beacons or target < 0:
        return None
    valid = [b for b in beacons if b >= 0]
    if not valid:
        return None
    return min(valid, key=lambda b: (bin(b ^ target).count('1'), -b))

def extract_header_slices(headers, low, high):
    if low > high or low < 0:
        return []
    mask = (1 << (high - low + 1)) - 1
    return sorted(((h >> low) & mask for h in headers), reverse=True)

def two_bit_channel_flags(flags):
    res = set()
    for f in flags:
        if f > 0:
            rem = f ^ (1 << (f.bit_length() - 1))
            if rem > 0 and (rem & (rem - 1)) == 0:
                res.add(f)
    return sorted(res)

def interleave_tile_coords(x, y):
    if x < 0 or y < 0:
        return -1
    res = 0
    for i in range(4):
        res |= ((x >> i) & 1) << (2 * i)
        res |= ((y >> i) & 1) << (2 * i + 1)
    return res

def sort_plane_seats(seats):
    order = {'A': 0, 'F': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5}
    return sorted(seats, key=lambda s: (int(s[:-1]), order[s[-1]]))

def order_crate_coords(coords):
    if not coords:
        return None
    return sorted(coords, key=lambda p: (abs(p[0]) + abs(p[1]), p[0], -p[1]))

def sort_version_tags(versions):
    def key(v):
        maj, min_s = v.split('.')
        return (int(maj), int(min_s), len(min_s) > 1 and min_s.startswith('0'), len(min_s))
    return sorted(versions, key=key)

def parse_shelf_spans(s):
    if not s or not s.strip():
        return []
    res = set()
    for part in s.split(','):
        part = part.strip()
        if not part:
            continue
        if '-' in part:
            a, b = map(int, part.split('-'))
            res.update(range(a, b + 1))
        else:
            res.add(int(part))
    return sorted(res)

def positive_sensors(log):
    totals = {}
    for item in log.split():
        name, val = item.split(':')
        totals[name] = totals.get(name, 0) + int(val)
    return sorted(k for k, v in totals.items() if v > 0)

def total_playlist_seconds(playlist):
    total = 0
    for track in playlist.split(';'):
        track = track.strip()
        if track:
            m, s = map(int, track.split(':'))
            total += m * 60 + s
    return total

def parse_config_lines(text):
    cfg = {}
    for line in text.splitlines():
        if '=' in line:
            k, v = line.split('=', 1)
            cfg[k.strip()] = v.strip()
    return cfg

def map_seat_bookings(bookings):
    rows = {}
    for b in bookings.split(','):
        b = b.strip()
        if b:
            row = int(b[:-1])
            seat = b[-1]
            rows.setdefault(row, set()).add(seat)
    return {r: sorted(s) for r, s in rows.items()}

def ledger_summary(entries):
    bal = 0
    low = 0
    for token in entries.split():
        bal += int(token)
        if bal < low:
            low = bal
    return (bal, low)

def latest_version(versions):
    if not versions:
        return None
    return max(versions, key=lambda v: tuple(map(int, v.split('.'))))

def extract_hashtags(post):
    seen = []
    for word in post.split():
        if word.startswith('#') and len(word) > 1 and word[1:].isalnum():
            tag = word[1:].lower()
            if tag not in seen:
                seen.append(tag)
    return seen

def best_team_index(records):
    best_idx, best_rate = -1, -1.0
    for idx, rec in enumerate(records.split()):
        w, l = map(int, rec.split('/'))
        if w + l > 0:
            rate = w / (w + l)
            if rate > best_rate:
                best_rate, best_idx = rate, idx
    return best_idx

def critical_sensor(readings):
    if not readings:
        return None
    best_idx = 0
    for i, (_, temp, hum) in enumerate(readings):
        _, b_temp, b_hum = readings[best_idx]
        if (temp, -hum, i) > (b_temp, -b_hum, best_idx):
            best_idx = i
    return readings[best_idx][0]

def compact_shelf(records):
    res = []
    for code, qty in records:
        if res and res[-1][0] == code:
            res[-1] = (code, res[-1][1] + qty)
        else:
            res.append((code, qty))
    return [r for r in res if r[1] != 0]

def fit_playlist(tracks, max_seconds):
    res, seen, total = [], set(), 0
    for title, sec in tracks:
        if sec <= 0 or title in seen:
            continue
        if total + sec > max_seconds:
            break
        res.append(title)
        seen.add(title)
        total += sec
    return tuple(res)

def audit_tickets(tickets):
    seen = set()
    total, count = 0, 0
    for code, cents, used in tickets:
        if not used and cents > 0 and code not in seen:
            seen.add(code)
            total += cents
            count += 1
    return (total, count)

def pair_parcels(parcels, limit):
    items = sorted(parcels, key=lambda x: (x[1], x[0]))
    used, pairs = [False] * len(items), []
    for i in range(len(items)):
        if used[i]:
            continue
        for j in range(i + 1, len(items)):
            if not used[j] and items[i][1] + items[j][1] <= limit:
                used[i] = used[j] = True
                u, v = sorted((items[i][0], items[j][0]))
                pairs.append((u, v))
                break
    return sorted(pairs)

def deep_zones(events, target_depth):
    by_time = {}
    for t, d in events:
        by_time[t] = by_time.get(t, 0) + d
    times = sorted(by_time)
    res, depth = [], 0
    for i, t in enumerate(times):
        depth += by_time[t]
        if depth < target_depth and i + 1 < len(times) and times[i + 1] > t:
            res.append((t, times[i + 1], depth))
    return tuple(res)

def standings_table(records):
    ordered = sorted(records, key=lambda r: (-(r[1] - r[2]), -r[1], r[0]))
    res = []
    for i, rec in enumerate(ordered):
        if i > 0 and (rec[1] - rec[2], rec[1]) == (ordered[i-1][1] - ordered[i-1][2], ordered[i-1][1]):
            rank = res[-1][0]
        else:
            rank = i + 1
        res.append((rank, rec[0]))
    return res

def menu_calories(items):
    valid = []
    for dish, grams, cal100 in items:
        if grams > 0 and cal100 >= 0:
            cals = int(round(grams * cal100 / 100))
            valid.append((dish, cals))
    valid.sort(key=lambda x: (-x[1], x[0]))
    return tuple(valid)

def peak_concurrency_time(sessions, k):
    if k <= 0:
        return 0
    points = sorted({t for _, s, e in sessions if s < e for t in (s, e)})
    for t in points:
        active = {u for u, s, e in sessions if s < e and s <= t < e}
        if len(active) >= k:
            return t
    return None

def rank_aisles(codes_str):
    max_nums = {}
    for token in codes_str.split():
        if '-' in token:
            aisle, num = token.split('-', 1)
            if len(aisle) == 1 and aisle.isupper():
                try:
                    val = int(num)
                    if aisle not in max_nums or val > max_nums[aisle]:
                        max_nums[aisle] = val
                except ValueError:
                    pass
    return tuple(sorted(max_nums, key=lambda k: (-max_nums[k], k)))

def longest_free_seat_run(row):
    max_run = 0
    current = 0
    for ch in row:
        if ch == '.':
            current += 1
            if current > max_run:
                max_run = current
        else:
            current = 0
    return max_run

def average_playlist_seconds(playlist):
    tracks = playlist.split()
    if not tracks:
        return 0.0
    total = 0
    for t in tracks:
        m, s = t.split(':')
        total += int(m) * 60 + int(s)
    return float(total / len(tracks))

def dedupe_caption_words(caption):
    res = []
    for w in caption.split():
        if not res or res[-1].lower() != w.lower():
            res.append(w)
    return ' '.join(res)

def top_batch_prefix(labels):
    counts = {}
    for lbl in labels:
        if ':' in lbl:
            p = lbl.split(':', 1)[0]
            counts[p] = counts.get(p, 0) + 1
    if not counts:
        return None
    return max(counts, key=lambda k: (counts[k], k))

def rover_position(cmds):
    pos = 0
    last = 0
    for ch in cmds:
        if ch == 'L':
            pos -= 1
            last = -1
        elif ch == 'R':
            pos += 1
            last = 1
        elif ch.isdigit():
            pos += last * (int(ch) - 1)
            last = 0
    return pos

def shared_catalog_letters(code):
    parts = code.split('/')
    if len(parts) < 2:
        return []
    left = {c for c in parts[0] if c.islower()}
    right = {c for c in parts[1] if c.islower()}
    return sorted(left & right)

def positive_ticket_balances(adjustments):
    totals = {}
    for code, delta in adjustments:
        totals[code] = totals.get(code, 0) + delta
    return {k: v for k, v in totals.items() if v > 0}

def frequent_playlist_durations(durations, k):
    counts = {}
    for d in durations:
        counts[d] = counts.get(d, 0) + 1
    res = [d for d, c in counts.items() if c >= k]
    return tuple(sorted(res, reverse=True))

def invert_seat_map(seat_map):
    inv = {}
    for seat, passenger in seat_map.items():
        if passenger:
            inv.setdefault(passenger, []).append(seat)
    return {p: tuple(sorted(seats)) for p, seats in inv.items()}

def count_odd_positive_weights(weights):
    counts = {}
    for w in weights:
        if w > 0:
            counts[w] = counts.get(w, 0) + 1
    return sum(1 for c in counts.values() if c % 2 == 1)

def merge_min_positive_stock(inv1, inv2):
    merged = {}
    for k in set(inv1) | set(inv2):
        val = min(inv1[k], inv2[k]) if k in inv1 and k in inv2 else inv1.get(k, inv2.get(k))
        if val > 0:
            merged[k] = val
    return merged

def average_badge_scores(records):
    sums = {}
    counts = {}
    for b_id, score in records:
        sums[b_id] = sums.get(b_id, 0) + score
        counts[b_id] = counts.get(b_id, 0) + 1
    return {b_id: sums[b_id] // counts[b_id] for b_id in sums}

def second_most_visited_room(visits):
    counts = {}
    for r in visits:
        counts[r] = counts.get(r, 0) + 1
    if len(counts) < 2:
        return None
    ordered = sorted(counts, key=lambda r: (-counts[r], r))
    return ordered[1]

def batch_length_frequencies(codes):
    counts = {}
    for c in codes:
        n = len(c)
        counts[n] = counts.get(n, 0) + 1
    return sorted(counts.items(), key=lambda x: (x[1], -x[0]))

def longest_shelf_span(ranges):
    if not ranges:
        return None
    return tuple(min(ranges, key=lambda r: (-(r[1] - r[0] + 1), r[0])))

def contested_tickets(blocks):
    seen, dup = set(), set()
    for s, e in blocks:
        for t in range(s, e + 1):
            (dup if t in seen else seen).add(t)
    return sorted(dup)

def clamp_sensor_readings(readings, low, high):
    if low > high:
        return []
    return sorted({max(low, min(high, r)) for r in readings})

def bounding_clip_window(clips):
    valid = [(s, e) for s, e in clips if e > s]
    if not valid:
        return (0, 0)
    return (min(s for s, _ in valid), max(e for _, e in valid))

def group_seat_runs(seats, max_gap):
    if not seats:
        return []
    runs = [[seats[0], seats[0]]]
    for s in seats[1:]:
        if s - runs[-1][1] <= max_gap:
            runs[-1][1] = s
        else:
            runs.append([s, s])
    return [tuple(r) for r in runs]

def common_slot_duration(slots):
    if not slots:
        return 0
    low = max(s for s, _ in slots)
    high = min(e for _, e in slots)
    return max(0, high - low)

def trim_muted_track(track, mute):
    ts, te = track
    ms, me = mute
    if te <= ts:
        return []
    if me <= ms or me <= ts or ms >= te:
        return [(ts, te)]
    return [(s, e) for s, e in ((ts, min(te, ms)), (max(ts, me), te)) if e > s]

def narrowest_band_midpoint(bands):
    if not bands:
        return None
    low, high = min(bands, key=lambda b: (b[1] - b[0], -b[0]))
    return float(low + high) / 2.0

def count_strict_subwindows(windows, target):
    ts, te = target
    valid = {
        (s, e) for s, e in windows
        if s <= e and ts <= s and e <= te and (e - s) < (te - ts)
    }
    return len(valid)

def generate_shelf_codes(letters):
    chars = sorted(set(letters))
    res = []
    for a in chars:
        for b in chars:
            if a != b:
                for c in chars:
                    if b != c:
                        res.append(a + b + c)
    return tuple(res)

def count_distant_seat_pairs(row, k):
    zeros = [i for i, val in enumerate(row) if val == 0]
    count = 0
    for idx, i in enumerate(zeros):
        for j in zeros[idx + 1:]:
            if j - i - 1 >= k:
                count += 1
    return count

from itertools import permutations

def monotonic_trios(lengths):
    res = [p for p in permutations(lengths, 3) if p[0] < p[1] < p[2] or p[0] > p[1] > p[2]]
    return sorted(res)

from itertools import combinations
from math import prod

def best_badge_team(badges, k):
    if k < 0 or k > len(badges):
        return None
    combs = [tuple(sorted(c)) for c in combinations(badges, k)]
    return max(combs, key=lambda c: (prod(c), c))

from itertools import permutations

def count_valid_crate_orders(crates):
    if not crates:
        return 1
    valid = set()
    for p in permutations(crates):
        if all(p[i] != p[i+1] for i in range(len(p) - 1)):
            valid.add(p)
    return len(valid)

from itertools import combinations

def count_equal_parcel_splits(weights):
    n = len(weights)
    total = sum(weights)
    count = 0
    for r in range(1, n):
        for sub in combinations(weights, r):
            if sum(sub) * 2 == total:
                count += 1
    return count // 2

from itertools import combinations

def count_distinct_flavor_picks(jars, k):
    if k < 0:
        return 0
    count = 0
    for r in range(min(k, len(jars)) + 1):
        for comb in combinations(jars, r):
            if len(set(comb)) == r:
                count += 1
    return count

from itertools import combinations

def split_ticket_code(ticket, k):
    n = len(ticket)
    if k <= 0 or k > n:
        return []
    res = []
    for cuts in combinations(range(1, n), k - 1):
         bounds = (0,) + cuts + (n,)
         res.append(tuple(ticket[bounds[i]:bounds[i+1]] for i in range(k)))
    return sorted(res)

def repeated_shelf_labels(labels):
    seen = set()
    added = set()
    result = []
    for label in labels:
        if label in seen and label not in added:
            result.append(label)
            added.add(label)
        seen.add(label)
    return result

def fill_sensor_gaps(readings):
    result = []
    last = None
    for r in readings:
        if r is not None:
            last = r
        result.append(last)
    return result

def closest_ticket_price(prices, target):
    if not prices:
        return None
    return min(prices, key=lambda p: (abs(p - target), p))

def pack_playlist_chunks(lengths, limit):
    if not lengths:
        return []
    chunks = [[lengths[0]]]
    current_sum = lengths[0]
    for x in lengths[1:]:
        if current_sum + x <= limit:
            chunks[-1].append(x)
            current_sum += x
        else:
            chunks.append([x])
            current_sum = x
    return chunks

def empty_aisle_seats(seats):
    zeros = [i for i, s in enumerate(seats) if s == 0]
    if len(zeros) < 2:
        return []
    return [ seats[i] for i in range(zeros[0] + 1, zeros[-1]) if seats[i] > max(seats[zeros[0]:i]) ]

def first_overdraft_balance(changes):
    bal = 0
    for c in changes:
        bal += c
        if bal < 0:
            return bal
    return bal

def trim_extreme_crates(weights):
    if len(weights) <= 2:
        return ()
    res = list(weights)
    res.remove(min(res))
    res.remove(max(res))
    return tuple(res)

def count_thaw_streaks(temps):
    streaks = 0
    in_streak = False
    for t in temps:
        if t > 0:
            if not in_streak:
                streaks += 1
                in_streak = True
        else:
            in_streak = False
    return streaks

def record_breaking_bids(bids):
    records = []
    for b in bids:
        if not records or b > records[-1]:
            records.append(b)
    return records

def smooth_sensor_readings(readings):
    res = list(readings[:2])
    for _ in range(2, len(readings)):
        res.append((res[-1] + res[-2]) // 2)
    return tuple(res)

def generate_ticket_codes(s, n):
    if n <= 0:
        return []
    codes = [s]
    for _ in range(n - 1):
        codes.append(codes[-1] + abs(codes[-1]) % 10)
    return codes

def collapse_altitude_markers(markers):
    curr = list(markers)
    while len(curr) > 1 and len(set(curr)) > 1:
        curr = [curr[i+1] - curr[i] for i in range(len(curr) - 1)]
    return tuple(curr)

def simulate_battery_levels(initial_level, delta, n):
    if n <= 0:
        return []
    res = [initial_level]
    for _ in range(n - 1):
        cur = res[-1]
        res.append(cur // 2 if cur % 2 == 0 else cur + delta)
    return res

def find_seat_cycle_start(s0, s1, m):
    if m <= 0:
        return None
    seen = {(s0, s1): 0}
    a, b, idx = s0, s1, 1
    while True:
        a, b = b, (a + b) % m
        if (a, b) in seen:
            return seen[(a, b)]
        seen[(a, b)] = idx
        idx += 1

def interleave_price_sequences(p1, p2):
    i, j, res = 0, 0, []
    while i < len(p1) and j < len(p2):
        if p1[i] <= p2[j]:
            res.append(p1[i]); i += 1
        else:
            res.append(p2[j]); j += 1
    return res + list(p1[i:]) + list(p2[j:])

def extract_bay_numbers(label_str):
    res = set()
    for part in label_str.split(','):
        part = part.strip()
        if part.startswith('-'):
            if part[1:].isdigit():
                res.add(int(part))
        elif part.isdigit():
            res.add(int(part))
    return sorted(res)

def longest_open_block(row):
    best_start, best_len = None, 0
    cur_start, cur_len = 0, 0
    for i, ch in enumerate(row):
        if ch == 'O':
            if cur_len == 0:
                cur_start = i
            cur_len += 1
            if cur_len > best_len:
                best_len, best_start = cur_len, cur_start
        else:
            cur_len = 0
    return (best_start, best_len)

def sum_sensor_readings(log):
    total = 0
    for token in log.split():
        if token.count('=') == 1:
            k, v = token.split('=')
            if k and (v.isdigit() or (v.startswith('-') and v[1:].isdigit())):
                total += int(v)
    return total

def normalize_shelf_code(code):
    parts = [p.upper() for p in code.split('-') if p != '']
    return '-'.join(parts)

def top_parcel_zone(parcels):
    counts = {}
    for p in parcels:
        if p and p[0].isalpha():
            ch = p[0].upper()
            counts[ch] = counts.get(ch, 0) + 1
    if not counts:
        return None
    return min(counts, key=lambda k: (-counts[k], k))

def redact_ticket(ticket):
    n = len(ticket)
    if n <= 4:
        return '*' * n
    return ticket[:2] + '*' * (n - 4) + ticket[-2:]

def split_route_path(path):
    if '/' not in path:
        return ('', path)
    idx = path.rfind('/')
    d, f = path[:idx], path[idx+1:]
    return (d if d != '' else '/', f)

def ledger_net_balance(ledger):
    total = 0
    for entry in ledger.split(','):
        s = entry.strip()
        if not s:
            continue
        if s[0] not in '+-' or not s[1:].isdigit():
            return None
        total += int(s)
    return total

def loan_end_weekday(start_day, duration):
    if duration < 0:
        return None
    return (start_day - 1 + duration) % 7 + 1

def first_joint_alarm(d1, p1, d2, p2):
    start = max(d1, d2, 1)
    for d in range(start, start + p1 * p2 + 1):
        if d >= d1 and d >= d2 and (d - d1) % p1 == 0 and (d - d2) % p2 == 0:
            return d
    return None

def locate_shift_time(offset):
    total_days, hour = divmod(offset, 24)
    week, day_idx = divmod(total_days, 7)
    return (week, day_idx + 1, hour)

def longest_gym_streak(days):
    s = set(days)
    best = 0
    for d in s:
        if d - 1 not in s:
            cur = d
            while cur in s:
                cur += 1
            best = max(best, cur - d)
    return best

def advance_parcel_days(start, n, closed_weekdays):
    if n < 0:
        return None
    closed = set(closed_weekdays)
    if {1, 2, 3, 4, 5, 6, 7}.issubset(closed):
        return None
    cur = start
    while (cur - 1) % 7 + 1 in closed:
        cur += 1
    while n > 0:
        cur += 1
        if (cur - 1) % 7 + 1 not in closed:
            n -= 1
    return cur

def peak_outage_month(month_lengths, outage_days):
    total = sum(month_lengths)
    counts = [0] * len(month_lengths)
    for d in outage_days:
        if 1 <= d <= total:
            rem = d
            for i, m in enumerate(month_lengths):
                if rem <= m:
                    counts[i] += 1
                    break
                rem -= m
    return counts.index(max(counts)) + 1 if any(counts) else None

def merge_cabin_bookings(bookings):
    valid = sorted((s, e) for s, e in bookings if s <= e)
    res = []
    for s, e in valid:
        if res and s <= res[-1][1] + 1:
            res[-1] = (res[-1][0], max(res[-1][1], e))
        else:
            res.append((s, e))
    return res

def days_until_anniversary(current_day, target_day, year_len):
    if year_len < 1 or not (1 <= current_day <= year_len) or not (1 <= target_day <= year_len):
        return None
    return (target_day - current_day) % year_len

def pack_trucks(weights, cap):
    trucks, curr, has_items = [], 0, False
    for w in weights:
        if w > cap:
            continue
        if has_items and curr + w > cap:
            trucks.append(curr)
            curr = w
        else:
            curr += w
            has_items = True
    if has_items:
        trucks.append(curr)
    return tuple(trucks)

def select_coupons(coupons, bill, k):
    chosen = []
    for c in sorted(coupons, reverse=True):
        if c > 0 and len(chosen) < k and c <= bill:
            chosen.append(c)
            bill -= c
    return chosen

def match_shoes(shoes, feet, tol):
    feet = sorted(feet)
    i = count = 0
    for s in sorted(shoes):
        while i < len(feet) and feet[i] < s:
            i += 1
        if i < len(feet) and feet[i] <= s + tol:
            count += 1
            i += 1
    return count

def build_playlist(durations, limit):
    picked = []
    for dur, idx in sorted((d, i) for i, d in enumerate(durations)):
        if dur <= limit:
            picked.append(idx)
            limit -= dur
    return picked

def unseated_groups(groups, tables):
    avail = sorted(tables)
    unseated = 0
    for g in groups:
        for i, t in enumerate(avail):
            if t >= g:
                avail.pop(i)
                break
        else:
            unseated += 1
    return unseated

def min_batteries(charges, target):
    if target <= 0:
        return 0
    count = 0
    for c in sorted((x for x in charges if x > 0), reverse=True):
        target -= c
        count += 1
        if target <= 0:
            return count
    return None

def merge_labels(labels, max_len):
    res = []
    for lbl in labels:
        if res and len(res[-1]) + 1 + len(lbl) <= max_len:
            res[-1] = res[-1] + '-' + lbl
        else:
            res.append(lbl)
    return res

def sell_tickets(bids, limit):
    valid = sorted((b for b in bids if b > 0), reverse=True)[:max(0, limit)]
    return (sum(valid), max(0, limit) - len(valid))

def place_routers(houses, radius):
    count, cov = 0, None
    for h in houses:
        if cov is None or h > cov:
            count += 1
            cov = h + 2 * radius
    return count

def ticket_digit_density(code):
    chars = [c for c in code if not c.isspace()]
    if not chars:
        return 0.0
    digits = sum(1 for c in chars if c.isdigit())
    return float(digits) / len(chars)

def open_seat_run_bounds(seat_map):
    runs = [len(r) for r in seat_map.split("X") if r]
    if not runs:
        return (0, 0)
    return (min(runs), max(runs))

def loud_sensor_lines(log):
    count = 0
    for line in log.splitlines():
        up = sum(1 for c in line if c.isupper())
        lo = sum(1 for c in line if c.islower())
        if up > lo:
            count += 1
    return count

def telegraph_polarity_balance(tape):
    plus = tape.count("+")
    minus = tape.count("-")
    if plus == 0 and minus == 0:
        return None
    return plus - minus

def rank_bird_call_vowels(call):
    low = call.lower()
    present = {v: low.count(v) for v in "aeiou" if v in low}
    return sorted(present, key=lambda v: (-present[v], v))

def count_bookend_chat_tokens(msg):
    count = 0
    for tok in msg.split():
        if len(tok) > 1 and tok[0].isalpha() and tok[0].lower() == tok[-1].lower():
            count += 1
    return count

def title_word_length_span(title):
    lengths = [len(w) for w in title.split()]
    if len(lengths) < 2:
        return 0
    return max(lengths) - min(lengths)

def collapse_shelf_counts(records):
    res = []
    for shelf, count in records:
        if res and res[-1][0] == shelf:
            res[-1] = (shelf, res[-1][1] + count)
        else:
            res.append((shelf, count))
    return [r for r in res if r[1] > 0]

def second_tier_seats(tickets):
    prices = sorted({p for _, p in tickets}, reverse=True)
    if len(prices) < 2:
        return ()
    target = prices[1]
    seen = set()
    res = []
    for seat, price in tickets:
        if price == target and seat not in seen:
            seen.add(seat)
            res.append(seat)
    return tuple(res)

def normalize_playlist(songs, max_seconds):
    res = []
    for title, mins, secs in songs:
        total = mins * 60 + secs
        if 0 < total < max_seconds:
            res.append((title, total))
    return res

def altitude_steps(waypoints):
    return tuple(
        (waypoints[i][0], waypoints[i][1] - waypoints[i - 1][1])
        for i in range(1, len(waypoints))
    )

def rank_couriers(records):
    from fractions import Fraction
    def key(rec):
        cid, km, pkgs = rec
        if km <= 0:
            return (1, Fraction(0), cid)
        return (0, -Fraction(pkgs, km), cid)
    return sorted(records, key=key)

def badge_active_spans(logs):
    by_badge = {}
    for badge, hr in logs:
        by_badge.setdefault(badge, set()).add(hr)
    return [
        (b, min(hrs), max(hrs))
        for b, hrs in sorted(by_badge.items())
        if len(hrs) >= 2
    ]

def zone_temp_drifts(readings):
    last = {}
    res = []
    for zone, temp in readings:
        res.append((zone, temp - last[zone] if zone in last else 0))
        last[zone] = temp
    return res

def peak_playlist_index(durations):
    if not durations:
        return None
    curr = 0
    max_val = None
    best_idx = 0
    for i, d in enumerate(durations):
        curr += d
        if max_val is None or curr >= max_val:
            max_val = curr
            best_idx = i
    return best_idx

def visited_altitudes(steps):
    curr = 0
    seen = {0}
    for s in steps:
        curr += s
        seen.add(curr)
    return tuple(sorted(seen))

def count_inventory_flips(shipments):
    curr = 0
    last_sign = 0
    flips = 0
    for s in shipments:
        curr += s
        if curr != 0:
            sign = 1 if curr > 0 else -1
            if last_sign != 0 and sign != last_sign:
                flips += 1
            last_sign = sign
    return flips

def overflow_batch_number(batches, capacity):
    curr = 0
    for i, b in enumerate(batches, 1):
        curr += b
        if curr > capacity:
            return i
    return 0

def longest_overdraft_streak(changes):
    curr = 0
    streak = 0
    best = 0
    for c in changes:
        curr += c
        if curr < 0:
            streak += 1
            if streak > best:
                best = streak
        else:
            streak = 0
    return best

def repeated_delta_checkpoints(deltas):
    curr = 0
    seen = {0}
    res = []
    for i, d in enumerate(deltas):
        curr += d
        if curr in seen:
            res.append(i)
        else:
            seen.add(curr)
    return res

def collapse_shelf_bays(records):
    res = []
    for bay, weight in records:
        if res and res[-1][0] == bay:
            res[-1] = (bay, res[-1][1] + weight)
        else:
            res.append((bay, weight))
    return tuple(res)

def above_average_seats(tickets):
    if not tickets:
        return []
    avg = sum(p for _, p in tickets) / len(tickets)
    return sorted({s for s, p in tickets if p > avg})

def settle_ledgers(transfers):
    bal = {}
    for payer, payee, amt in transfers:
        bal[payer] = bal.get(payer, 0) - amt
        bal[payee] = bal.get(payee, 0) + amt
    return [ (k, v) for k, v in sorted(bal.items(), key=lambda x: (x[1], x[0])) ]

def total_playlist_time(tracks):
    total = sum(m * 60 + s for _, m, s in tracks if m >= 0 and s >= 0)
    return (total // 3600, (total % 3600) // 60, total % 60)

def latest_positive_stock(updates):
    last = {}
    for sku, qty in updates:
        last.pop(sku, None)
        last[sku] = qty
    return [(sku, qty) for sku, qty in last.items() if qty > 0]

def overlapping_beacons(beacons, query):
    qs, qe = query
    return tuple((s, e) for s, e in beacons if max(s, qs) <= min(e, qe))

def bucket_runners_by_minute(results):
    groups = {}
    for name, sec in results:
        groups.setdefault(sec // 60, []).append(name)
    return [(m, tuple(groups[m])) for m in sorted(groups)]

def largest_valid_crate(crates):
    best_id, best_vol = None, -1
    for cid, w, h, d in crates:
        if w > 0 and h > 0 and d > 0 and w * h * d > best_vol:
            best_id, best_vol = cid, w * h * d
    return best_id

def equal_seat_blocks(row, k):
    if k <= 0 or len(row) < 2 * k:
        return 0
    n = len(row)
    sums = [sum(row[i:i+k]) for i in range(n - k + 1)]
    ans = 0
    for i in range(len(sums)):
        for j in range(i + k, len(sums)):
            if sums[i] == sums[j]:
                ans += 1
    return ans

def valid_playlists(lengths, d):
    if d < 0:
        return []
    res = [[x] for x in sorted(set(lengths))]
    for seq in res:
        for x in sorted(set(lengths)):
            if x > seq[-1] and x - seq[-1] <= d:
                res.append(seq + [x])
    return sorted(res, key=lambda s: (len(s), s))

def even_coin_subsets(coins):
    dp = [1, 0]
    for c in coins:
        if c % 2 == 0:
            dp = [dp[0] * 2, dp[1] * 2]
        else:
            dp = [dp[0] + dp[1], dp[0] + dp[1]]
    return dp[0] - 1

def count_task_splits(n, k, lo, hi):
    if lo > hi or k < 0 or (k == 0 and n != 0):
        return 0
    dp = {0: 1}
    for _ in range(k):
        dp = {s + x: sum(dp.get(s, 0) for x in range(lo, hi + 1) if s + x == t) for t in range(k * lo, k * hi + 1) for s in [t - lo] if False} or {t: sum(dp.get(t - x, 0) for x in range(lo, hi + 1)) for t in range(min(dp) + lo, max(dp) + hi + 1)}
    return dp.get(n, 0)

def count_budget_pairs(prices, budget):
    l, r = 0, len(prices) - 1
    count = 0
    while l < r:
        if prices[l] + prices[r] <= budget:
            count += 1
            l += 1
            r -= 1
        else:
            r -= 1
    return count

def shift_zero_tracks(tracks):
    res = list(tracks)
    write = 0
    for read in range(len(res)):
        if res[read] != 0:
            res[write], res[read] = res[read], res[write]
            write += 1
    return (res, len(res) - write)

def longest_valid_shelf(labels, k):
    if not labels or k < 0:
        return None
    l = 0
    best = (0, 0)
    for r in range(len(labels)):
        while l <= r and labels[r] - labels[l] > k:
            l += 1
        if l <= r and (r - l) > (best[1] - best[0]):
            best = (l, r)
    return best

def merge_unique_crates(a, b):
    banned = {a[k] for k in range(min(len(a), len(b))) if a[k] == b[k]}
    i, j = len(a) - 1, len(b) - 1
    res = []
    while i >= 0 or j >= 0:
        val = a[i] if (j < 0 or (i >= 0 and a[i] > b[j])) else b[j]
        if i >= 0 and val == a[i]: i -= 1
        else: j -= 1
        if val not in banned and (not res or res[-1] != val):
            res.append(val)
    return res

def check_seat_symmetry(seats):
    l, r = 0, len(seats) - 1
    while l < r:
        if seats[l] == '-': l += 1
        elif seats[r] == '-': r -= 1
        elif seats[l] != seats[r]: return (seats[l], seats[r])
        else: l += 1; r -= 1
    return True

def dedupe_badges_twice(badges):
    write = 0
    orig = len(badges)
    for b in badges:
        if write < 2 or b != badges[write - 2]:
            badges[write] = b
            write += 1
    del badges[write:]
    return (write, orig - write)

def intersect_log_times(log1, log2):
    i = j = 0
    res = []
    while i < len(log1) and j < len(log2):
        if log1[i] == log2[j]:
            res.append(log1[i])
            i += 1; j += 1
        elif log1[i] < log2[j]: i += 1
        else: j += 1
    return res

def find_beacon_meeting(steps):
    if not steps: return None
    l, r = 0, len(steps) - 1
    while l < r:
        if steps[l] <= 0 or steps[r] <= 0:
            return None
        l += steps[l]
        r -= steps[r]
    return l if l == r else None

def exclusive_sensor_readings(log1, log2):
    banned = set(log2)
    seen = set()
    result = []
    for r in log1:
        if r not in banned and r not in seen:
            seen.add(r)
            result.append(r)
    return tuple(result)

def smallest_exclusive_ticket(booth_a, booth_b):
    sym_diff = set(booth_a) ^ set(booth_b)
    return min(sym_diff) if sym_diff else None

def duplicate_shelf_labels(labels):
    seen = set()
    dups = set()
    for x in labels:
        if x in seen:
            dups.add(x)
        seen.add(x)
    return sorted(dups, reverse=True)

def common_seats(row_maps):
    if not row_maps:
        return []
    common = set(row_maps[0]).intersection(*row_maps[1:])
    return sorted(common)

def most_varied_playlist(playlists):
    if not playlists:
        return None
    return max(playlists, key=lambda p: len(set(p)))

def count_heavy_distinct_crates(weights):
    unique = set(weights)
    if not unique:
        return 0
    avg = sum(unique) / len(unique)
    return sum(1 for w in unique if w > avg)

def valid_master_keys(master, backup):
    master_set = set(master)
    return len(master) == len(master_set) and master_set.issubset(backup)

def second_lowest_elevation(markers):
    unique = sorted(set(markers))
    return unique[1] if len(unique) >= 2 else None

def shared_branch_coupons(b1, b2, b3):
    s1, s2, s3 = set(b1), set(b2), set(b3)
    shared = (s1 & s2) | (s2 & s3) | (s1 & s3)
    return sorted(shared)

def best_badge_id(badges):
    pos = [b for b in badges if b > 0]
    if not pos:
        return None
    def odd_divs(n):
        while n % 2 == 0:
            n //= 2
        return sum(1 for i in range(1, n + 1, 2) if n % i == 0)
    return min(pos, key=lambda x: (-odd_divs(x), x))

def valid_beacon_steps(beacons):
    if len(beacons) < 2:
        return ()
    diff = abs(beacons[0] - beacons[-1])
    if diff == 0:
        return ()
    divs = set()
    for i in range(1, int(diff**0.5) + 1):
        if diff % i == 0:
            divs.add(i)
            divs.add(diff // i)
    return tuple(sorted(divs))

import math
def min_coprime_pad(weight, limit):
    if weight <= 0 or limit <= 0:
        return None
    pad = 0
    while math.gcd(weight + pad, limit) != 1:
        pad += 1
    return pad

def squarefree_readings(readings):
    res = set()
    for r in readings:
        if r > 1 and all(r % (i * i) != 0 for i in range(2, int(r**0.5) + 1)):
            res.add(r)
    return sorted(res, reverse=True)

def heaviest_divisor_crate(crates):
    valid = [c for c in set(crates) if c > 1]
    if not valid:
        return None
    def lpd(n):
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return n // i
        return 1
    return min(valid, key=lambda x: (-lpd(x), x))

def gear_remainders(teeth, pitch):
    if pitch <= 0:
        return []
    return sorted({t % pitch for t in teeth})

def power_channels(channels, base):
    if base <= 0:
        return ()
    if base == 1:
        return tuple(c for c in channels if c == 1)
    res = []
    for c in channels:
        if c >= 1:
            t = c
            while t % base == 0:
                t //= base
            if t == 1:
                res.append(c)
    return tuple(res)

def dup_below_mean(readings):
    if not readings:
        return []
    mean = sum(readings) / len(readings)
    seen = []
    for r in readings:
        if r < mean and readings.count(r) >= 2 and r not in seen:
            seen.append(r)
    return seen

def price_jump_labels(labels, prices, limit):
    res = []
    for i in range(len(prices) - 1):
        if abs(prices[i] - prices[i + 1]) > limit:
            idx = i if prices[i] > prices[i + 1] else i + 1
            res.append(labels[idx])
    return res

def trim_playlist(lengths, cap):
    kept = list(lengths)
    trimmed = 0
    while kept and sum(kept) > cap:
        kept.pop()
        trimmed += 1
    return (kept, trimmed)

def best_empty_row(seat_map):
    best_row, best_len = None, 0
    for r_idx, row in enumerate(seat_map):
        cur = max_run = 0
        for seat in row:
            cur = cur + 1 if seat == 0 else 0
            if cur > max_run:
                max_run = cur
        if max_run > 0 and max_run >= best_len:
            best_row, best_len = r_idx, max_run
    return best_row

def interior_tickets(codes):
    if len(set(codes)) <= 2:
        return []
    lo, hi = min(codes), max(codes)
    return sorted({c for c in codes if lo < c < hi}, reverse=True)

def clean_crate_weights(weights, max_w):
    res = []
    last = None
    for w in weights:
        if 0 <= w <= max_w:
            last = w
            res.append(w)
        elif last is not None:
            res.append(last)
    return res

def fold_lap_diffs(laps):
    n = len(laps)
    return [abs(laps[i] - laps[n - 1 - i]) for i in range(n // 2)]

def rising_bid_pct(bids):
    nz = [b for b in bids if b != 0]
    if len(nz) < 2:
        return None
    ups = sum(1 for i in range(1, len(nz)) if nz[i] > nz[i - 1])
    return (ups * 100) // (len(nz) - 1)

def rotate_active_workers(workers, k):
    active = [w for w in workers if w != '']
    if not active:
        return []
    k %= len(active)
    return active[k:] + active[:k]

def first_overdraft_index(changes):
    total = 0
    for i, c in enumerate(changes):
        total += c
        if total < 0:
            return i
    return -1

def sort_seat_map(seats):
    def key_fn(s):
        row, col = int(s[:-1]), s[-1]
        return (row, abs(ord(col) - ord('D')), col)
    return sorted(seats, key=key_fn)

def sort_keys_by_mod(data):
    items = sorted(data.items(), key=lambda x: (x[1] % 10, x[0]))
    items_sorted = sorted(data.keys(), reverse=True)
    return sorted(items_sorted, key=lambda k: data[k] % 10)

def sort_crates_by_density(crates):
    def key_fn(c):
        cid, w, b = c
        density = w / b if b != 0 else 0.0
        return (-density, cid)
    return sorted(crates, key=key_fn)

def sort_versions_custom(versions):
    def key_fn(v):
        parts = v.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        return (major, -minor)
    return sorted(versions, key=key_fn)

def pack_shelf_bins(weights, cap):
    bins = []
    curr = 0
    has_items = False
    for w in weights:
        if w > cap:
            continue
        if has_items and curr + w > cap:
            bins.append(curr)
            curr = w
        else:
            curr += w
            has_items = True
    if has_items:
        bins.append(curr)
    return tuple(bins)

def pick_distinct_coupons(coupons, k):
    if k <= 0:
        return []
    pos = sorted({c for c in coupons if c > 0}, reverse=True)
    return pos[:k]

def select_playlist_indices(lengths, limit):
    candidates = sorted((val, i) for i, val in enumerate(lengths) if val > 0)
    chosen = []
    for val, i in candidates:
        if limit >= val:
            limit -= val
            chosen.append(i)
    return sorted(chosen)

def apply_single_rebates(price, rebates):
    for r in sorted(rebates, reverse=True):
        if 0 < r <= price:
            price -= r
    return int(price)

def pair_adjacent_badges(badges):
    res = []
    i = 0
    while i < len(badges) - 1:
        if badges[i] == badges[i + 1]:
            res.append(badges[i])
            i += 2
        else:
            i += 1
    return tuple(res)

def count_needed_batteries(charges, target):
    if target <= 0:
        return 0
    total = 0
    for i, c in enumerate(sorted((x for x in charges if x > 0), reverse=True), 1):
        total += c
        if total >= target:
            return i
    return None

def schedule_room_bookings(bookings):
    chosen = []
    last_end = None
    for s, e in sorted(bookings, key=lambda x: (x[1], x[0])):
        if last_end is None or s >= last_end:
            chosen.append([s, e])
            last_end = e
    return chosen

def densest_seat_row(seats):
    best_idx = -1
    best_ratio = -1.0
    for idx, row in enumerate(seats):
        if row:
            ratio = sum(row) / len(row)
            if ratio >= best_ratio:
                best_ratio = ratio
                best_idx = idx
    return best_idx

def border_panel_double_corners(grid):
    if not grid or not grid[0]:
        return 0
    R, C = len(grid), len(grid[0])
    total = 0
    for r in range(R):
        for c in range(C):
            on_r = (r == 0 or r == R - 1)
            on_c = (c == 0 or c == C - 1)
            if on_r and on_c:
                total += 2 * grid[r][c]
            elif on_r or on_c:
                total += grid[r][c]
    return total

def smooth_pixels_horizontal(img):
    res = []
    for row in img:
        n = len(row)
        if n <= 1:
            res.append(list(row))
        else:
            new_row = [row[1]] + [(row[i - 1] + row[i + 1]) // 2 for i in range(1, n - 1)] + [row[-2]]
            res.append(new_row)
    return res

def strictly_shorter_columns(orchard):
    if len(orchard) <= 1 or not orchard[0]:
        return 0
    count = 0
    for col in zip(*orchard):
        if all(col[i] > col[i + 1] for i in range(len(col) - 1)):
            count += 1
    return count

def lowest_positive_basin(terrain):
    best = None
    for r, row in enumerate(terrain):
        for c, val in enumerate(row):
            if val > 0:
                cand = (val, c, r)
                if best is None or cand < best:
                    best = cand
    return (best[2], best[1]) if best else None

def shift_display_frame(mat):
    if len(mat) <= 1 or not mat[0] or len(mat[0]) <= 1:
        return [row[:] for row in mat]
    R, C = len(mat), len(mat[0])
    res = [row[:] for row in mat]
    coords = [(0, c) for c in range(C)] + [(r, C - 1) for r in range(1, R - 1)] + [(R - 1, c) for c in range(C - 1, -1, -1)] + [(r, 0) for r in range(R - 2, 0, -1)]
    for i, (r, c) in enumerate(coords):
        pr, pc = coords[i - 1]
        res[r][c] = mat[pr][pc]
    return res

def transpose_jagged_playlists(lists):
    if not lists:
        return []
    max_len = max(len(r) for r in lists)
    padded = [ list(r) + [None] * (max_len - len(r)) for r in lists ]
    return list(zip(*padded))

def universal_crate_ids(grid):
    non_empty = [set(row) for row in grid if row]
    if not non_empty:
        return []
    return sorted(set.intersection(*non_empty))

def count_billing_days(start_day, end_day, k):
    if start_day > end_day or k <= 0:
        return 0
    return (end_day // k) - ((start_day - 1) // k)

def day_to_lunar_date(day_of_year, month_lengths):
    if day_of_year < 1 or day_of_year > sum(month_lengths):
        return None
    for i, length in enumerate(month_lengths, 1):
        if day_of_year <= length:
            return (i, day_of_year)
        day_of_year -= length

def busiest_weekday(offsets):
    if not offsets:
        return None
    counts = [0] * 7
    for d in offsets:
        counts[d % 7] += 1
    return counts.index(max(counts))

def coinciding_maintenance_days(s1, p1, s2, p2, horizon):
    if horizon < 0 or p1 <= 0 or p2 <= 0:
        return []
    d1 = set(range(max(0, s1), horizon + 1, p1)) if s1 >= 0 else {d for d in range(s1, horizon + 1, p1) if d >= 0}
    d2 = set(range(max(0, s2), horizon + 1, p2)) if s2 >= 0 else {d for d in range(s2, horizon + 1, p2) if d >= 0}
    return sorted(d1 & d2)

def max_delivery_drought(start, end, deliveries):
    if start > end:
        return 0
    valid = sorted({d for d in deliveries if start <= d <= end})
    pts = [start - 1] + valid + [end + 1]
    return max(pts[i+1] - pts[i] - 1 for i in range(len(pts) - 1))

def prorate_subscription_fee(fee, active_days, cycle_length):
    if cycle_length <= 0 or active_days < 0:
        return None
    from fractions import Fraction
    return round(Fraction(fee * active_days, cycle_length))

def last_peak_shelf(weights):
    if not weights:
        return None
    curr = 0
    max_w = None
    best_idx = 0
    for i, w in enumerate(weights):
        curr += w
        if max_w is None or curr >= max_w:
            max_w = curr
            best_idx = i
    return best_idx

def playable_track_count(durations, limit):
    curr = 0
    for i, d in enumerate(durations):
        curr += d
        if curr > limit:
            return i
    return len(durations)

def balanced_cabin_index(changes):
    total = sum(changes)
    left = 0
    for i, c in enumerate(changes):
        if left == total - left - c:
            return i
        left += c
    return -1

def positive_day_totals(rainfall):
    res = set()
    curr = 0
    for r in rainfall:
        curr += r
        if r > 0:
            res.add(curr)
    return sorted(res)

def shortest_goal_prefix(sales, goal):
    if goal <= 0:
        return []
    curr = 0
    for i, s in enumerate(sales):
        curr += s
        if curr >= goal:
            return sales[:i + 1]
    return None

def halving_cart_totals(prices):
    res = []
    curr = 0
    for p in prices:
        curr += p
        if curr % 2 == 0:
            curr //= 2
        res.append(curr)
    return res

def split_booking_totals(bookings):
    odds, evens = [], []
    o_sum = e_sum = 0
    for i, b in enumerate(bookings):
        if i % 2 == 1:
            o_sum += b
            odds.append(o_sum)
        else:
            e_sum += b
            evens.append(e_sum)
    return (odds, evens)

def extend_shelf_codes(codes, n):
    if n <= 0:
        return ()
    res = list(codes[:n])
    while len(res) < n:
        res.append(res[-1] - 2 * res[-2])
    return tuple(res)

def balanced_sensor_readings(readings):
    found = set()
    for i in range(1, len(readings) - 1):
        if 2 * readings[i] == readings[i - 1] + readings[i + 1]:
            found.add(readings[i])
    return sorted(found)

def playlist_durations(seed, n):
    if n <= 0:
        return []
    seq = [seed]
    for _ in range(n - 1):
        prev = seq[-1]
        seq.append(prev // 2 if prev % 2 == 0 else prev + 3)
    return seq

def first_discounted_ticket(prices):
    running_sum = 0
    for i, p in enumerate(prices):
        if p < running_sum:
            return i
        running_sum += p
    return -1

def reduce_crate_weights(weights, k):
    curr = list(weights)
    while len(curr) > max(0, k):
        if len(curr) <= 1:
            curr = []
        else:
            curr = [curr[i + 1] - curr[i] for i in range(len(curr) - 1)]
    return tuple(curr)

def valid_seat_prefix(seats):
    if not seats:
        return []
    res = [seats[0]]
    for s in seats[1:]:
        if res[-1] < s <= 2 * res[-1]:
            res.append(s)
        else:
            break
    return res

def nth_beacon_signal(a, b, n):
    if n < 0:
        return None
    if n == 0:
        return a
    prev, curr = a, b
    for k in range(2, n + 1):
        prev, curr = curr, (curr + prev if k % 2 == 0 else curr - prev)
    return curr

def last_unique_battery_level(levels):
    seen = set()
    last = None
    for x in levels:
        if x in seen:
            return last
        seen.add(x)
        last = x
    return last

def corridor_widths(w):
    res = []
    while w > 0:
        res.append(w)
        w //= 3
    return res

def last_min_shelf_load(changes):
    if not changes:
        return None
    curr = 0
    min_val = float('inf')
    ans = 0
    for i, x in enumerate(changes):
        curr += x
        if curr <= min_val:
            min_val = curr
            ans = i
    return ans

def unique_ticket_totals(sales):
    total = 0
    seen = set()
    for s in sales:
        if s != 0:
            total += s
            seen.add(total)
    return tuple(sorted(seen))

def first_song_over_limit(durations, limit):
    total = 0
    for i, d in enumerate(durations, 1):
        total += d
        if total > limit:
            return i
    return -1

def resetting_sensor_drift(adjustments):
    res = []
    curr = 0
    for a in adjustments:
        if a < 0:
            curr = 0
        else:
            curr += a
        res.append(curr)
    return res

def positive_occupancy_stops(boardings, initial):
    curr = initial
    count = 0
    for b in boardings:
        curr += b
        if curr > 0:
            count += 1
    return count

def max_elevation_step(gains):
    if len(gains) < 2:
        return 0
    return max(gains[1:])

def modulo_fee_totals(fees, divisor):
    res = []
    curr = 0
    for f in fees:
        curr = (curr + f) % divisor
        if curr == 0:
            break
        res.append(curr)
    return res

def parse_sensor_readings(line):
    result = {}
    for token in line.split():
        if token.count('=') == 1:
            k, v = token.split('=')
            if k and (v.isdigit() or (v.startswith('-') and v[1:].isdigit())):
                result[k] = int(v)
    return result

def extract_row_seats(row_spec):
    if ':' not in row_spec:
        return []
    _, seats = row_spec.split(':', 1)
    return [int(s) for s in seats.split(',') if s.strip()]

def cheapest_tagged_item(tags):
    best_item, best_price = None, None
    for entry in tags.split(';'):
        if ':' in entry:
            item, price = entry.split(':', 1)
            p = float(price)
            if best_price is None or p < best_price:
                best_item, best_price = item.strip(), p
    return best_item

def parse_version_path(path):
    parts = [p.strip() for p in path.split('/') if p.strip()]
    return tuple(int(p[1:]) if p[0] in 'vV' else int(p) for p in parts)

def positive_crate_codes(labels):
    totals = {}
    for line in labels.splitlines():
        if '#' in line:
            code, qty = line.split('#', 1)
            totals[code] = totals.get(code, 0) + int(qty)
    return [c for c, q in totals.items() if q > 0]

def parse_coord_pair(text):
    s = text.strip()
    if not (s.startswith('[') and s.endswith(']')):
        return None
    parts = s[1:-1].split(',')
    if len(parts) != 2:
        return None
    try:
        return (float(parts[0]), float(parts[1]))
    except ValueError:
        return None

def cheapest_valid_seat(records):
    valid = [r for r in records if r[2] > 0]
    if not valid:
        return None
    best = min(valid, key=lambda r: (r[2], r[0], r[1]))
    return (best[0], best[1])

def summarize_aisles(entries):
    totals = {}
    for aisle, count in entries:
        totals[aisle] = totals.get(aisle, 0) + count
    return tuple(sorted((a, t) for a, t in totals.items() if t != 0))

def widest_sensor_span(readings):
    if not readings:
        return None
    best_id, best_span = readings[0][0], readings[0][2] - readings[0][1]
    for sid, low, high in readings[1:]:
        if high - low >= best_span:
            best_id, best_span = sid, high - low
    return best_id

def short_playlist_titles(tracks, limit):
    seen = set()
    out = []
    for title, secs in tracks:
        if 0 < secs <= limit and title not in seen:
            seen.add(title)
            out.append(title)
    return tuple(out)

def consecutive_station_deltas(log):
    return [
        (log[i][0], log[i][1] - log[i - 1][1])
        for i in range(1, len(log))
        if log[i][0] == log[i - 1][0]
    ]

def clean_access_badges(events):
    ok = {b for b, _, a in events if a}
    bad = {b for b, _, a in events if not a}
    return sorted(ok - bad)

def clip_shifted_windows(windows, offset, limit):
    res = []
    for task, s, e in windows:
        ns, ne = max(0, s + offset), min(limit, e + offset)
        if ns < ne:
            res.append((task, ns, ne))
    return res

def rank_league_table(rows):
    ordered = sorted(rows, key=lambda r: (-(3 * r[1] + r[2]), -r[3], r[0]))
    return tuple(r[0] for r in ordered)

def unmatched_order_lines(requests, bins):
    pool = list(bins)
    unmatched = []
    for code, qty in requests:
        idx = next((i for i, (c, s) in enumerate(pool) if c == code and s >= qty), None)
        if idx is None:
            unmatched.append((code, qty))
        else:
            pool.pop(idx)
    return unmatched

def count_playlist_subsets(lengths, target):
    if target < 0:
        return 0
    sums = [0]
    for x in lengths:
        sums += [s + x for s in sums]
    return sums[1:].count(target)

def count_seat_placements(seats, k):
    if k == 0:
        return 1
    if k < 0 or not seats:
        return 0
    if seats[0] == 0:
        return count_seat_placements(seats[2:], k - 1) + count_seat_placements(seats[1:], k)
    return count_seat_placements(seats[1:], k)

def min_stamp_count(stamps, postage):
    if postage == 0:
        return 0
    dp = {0: 0}
    for s in stamps:
        for total, cnt in list(dp.items()):
            dp[total + s] = min(dp.get(total + s, len(stamps) + 1), cnt + 1)
    return dp.get(postage, None)

def count_menu_plans(menus):
    if not menus or any(not m for m in menus):
        return 0
    ways = [(d, 1) for d in menus[0]]
    for menu in menus[1:]:
        ways = [(d, sum(c for p, c in ways if p != d)) for d in menu]
    return sum(c for _, c in ways)

def tightest_crate_group(crates, k):
    if k <= 0 or k > len(crates):
        return None
    s = sorted(crates)
    groups = [tuple(s[i:i + k]) for i in range(len(s) - k + 1)]
    return min(groups, key=lambda g: (g[-1] - g[0], g))

def count_increasing_badges(badges, k):
    if k <= 0 or k > len(badges):
        return 0
    dp = [1] * len(badges)
    for _ in range(k - 1):
        dp = [sum(dp[i] for i in range(j) if badges[i] < badges[j]) for j in range(len(badges))]
    return sum(dp)

def lowest_unique_reading(readings):
    counts = {}
    for r in readings:
        counts[r] = counts.get(r, 0) + 1
    uniques = [r for r, c in counts.items() if c == 1]
    return min(uniques) if uniques else None

def shared_badge_ids(daily_logs):
    counts = {}
    for log in daily_logs:
        for badge in set(log):
            counts[badge] = counts.get(badge, 0) + 1
    return sorted(b for b, c in counts.items() if c >= 2)

def broadest_channel_index(channels):
    if not channels:
        return -1
    best_idx = 0
    best_count = -1
    for idx, listeners in enumerate(channels):
        count = len(set(listeners))
        if count > best_count:
            best_count = count
            best_idx = idx
    return best_idx

def average_unique_positive_duration(durations):
    pos = {d for d in durations if d > 0}
    return float(sum(pos) / len(pos)) if pos else 0.0

def symmetric_seat_bookings(morning, afternoon):
    diff = set(morning) ^ set(afternoon)
    return sorted(diff, reverse=True)

def runner_up_bid(bids):
    unique_bids = sorted(set(bids), reverse=True)
    return unique_bids[1] if len(unique_bids) >= 2 else None

def duplicate_coupons_lower(coupons):
    seen = set()
    dups = set()
    for c in coupons:
        low = c.lower()
        if low in seen:
            dups.add(low)
        seen.add(low)
    return tuple(sorted(dups))

def banner_areas(posts):
    areas = set()
    for (x1, y1), (x2, y2) in zip(posts, posts[1:]):
        area = abs(x1 - x2) * abs(y1 - y2)
        if area > 0:
            areas.add(area)
    return sorted(areas)

def closest_interior_sensor(sensors, box):
    x1, x2, y1, y2 = box
    valid = [(x, y) for x, y in sensors if x1 < x < x2 and y1 < y < y2]
    if not valid:
        return None
    return min(valid, key=lambda p: (p[0]**2 + p[1]**2, p[0], p[1]))

def count_lit_spotlights(lights, mic, r):
    if r < 0:
        return 0
    mx, my = mic
    return len({(x, y) for x, y in lights if (x - mx)**2 + (y - my)**2 <= r**2})

def first_integer_midpoint(checkpoints):
    for (x1, y1), (x2, y2) in zip(checkpoints, checkpoints[1:]):
        if (x1 + x2) % 2 == 0 and (y1 + y2) % 2 == 0:
            return ((x1 + x2) // 2, (y1 + y2) // 2)
    return None

def quadrant_one_bounds(seats):
    q1 = [(x, y) for x, y in seats if x > 0 and y > 0]
    if not q1:
        return None
    xs, ys = zip(*q1)
    return (min(xs), min(ys), max(xs), max(ys))

def plots_on_segment(plots, p1, p2):
    x1, y1 = p1
    x2, y2 = p2
    res = {
        (x, y) for x, y in plots
        if (x - x1) * (y2 - y1) == (y - y1) * (x2 - x1)
        and min(x1, x2) <= x <= max(x1, x2)
        and min(y1, y2) <= y <= max(y1, y2)
    }
    return sorted(res)

def orthogonal_path_length(path):
    total = 0
    for (x1, y1), (x2, y2) in zip(path, path[1:]):
        dx, dy = abs(x1 - x2), abs(y1 - y2)
        if (dx == 0) ^ (dy == 0):
            total += dx + dy
    return total

def rug_overlap_area(r1, r2):
    ax1, ay1, ax2, ay2 = r1
    bx1, by1, bx2, by2 = r2
    w = min(max(ax1, ax2), max(bx1, bx2)) - max(min(ax1, ax2), min(bx1, bx2))
    h = min(max(ay1, ay2), max(by1, by2)) - max(min(ay1, ay2), min(by1, by2))
    return max(0, w) * max(0, h)

def rotate_brackets(brackets, pivot, k):
    px, py = pivot
    res = []
    for x, y in brackets:
        dx, dy = x - px, y - py
        for _ in range(k % 4):
            dx, dy = -dy, dx
        res.append((px + dx, py + dy))
    return res

def ways_to_fill_playlist(durations, total):
    if total < 0:
        return 0
    count = 0
    for mask in range(1, 1 << len(durations)):
        if sum(durations[i] for i in range(len(durations)) if (mask >> i) & 1) == total:
            count += 1
    return count

def seat_non_adjacent_guests(seat_row, k):
    if k == 0:
        return 1
    if k < 0 or k > len(seat_row):
        return 0
    free = [i for i, s in enumerate(seat_row) if s == 0]
    from itertools import combinations
    return sum(1 for c in combinations(free, k) if all(b - a > 1 for a, b in zip(c, c[1:])))

def count_balanced_splits(crates, tol):
    n = len(crates)
    if n < 2 or tol < 0:
        return 0
    total = sum(crates)
    count = 0
    for mask in range(1, 1 << (n - 1)):
        s = sum(crates[i] for i in range(n) if (mask >> i) & 1)
        if abs(total - 2 * s) <= tol:
            count += 1
    return count

def two_digit_badges(digits):
    res = set()
    n = len(digits)
    for i in range(n):
        for j in range(n):
            if i != j:
                if digits[i] == 0 and digits[j] == 0:
                    res.add(0)
                elif digits[i] != 0:
                    res.add(digits[i] * 10 + digits[j])
    return sorted(res)

def all_team_pairings(players):
    if len(players) % 2 != 0:
        return []
    def helper(rem):
        if not rem:
            return {()}
        res = set()
        for i in range(1, len(rem)):
            pair = (rem[0], rem[i])
            for rest in helper(rem[1:i] + rem[i+1:]):
                res.add(tuple(sorted((pair,) + rest)))
        return res
    return [list(p) for p in sorted(helper(sorted(players)))]

def record_breaking_tracks(durations):
    if not durations:
        return ()
    res = [0]
    curr = durations[0]
    max_s = curr
    for i in range(1, len(durations)):
        curr += durations[i]
        if curr > max_s:
            max_s = curr
            res.append(i)
    return tuple(res)

def last_total_match_index(changes):
    if not changes:
        return None
    target = sum(changes)
    curr = 0
    ans = None
    for i, x in enumerate(changes):
        curr += x
        if curr == target:
            ans = i
    return ans

def distinct_nonzero_stack_weights(boxes):
    res = set()
    curr = 0
    for b in boxes:
        curr += b
        if b != 0:
            res.add(curr)
    return sorted(res)

def positive_paced_ticket_averages(sales):
    res = []
    curr = 0
    pos = 0
    for s in sales:
        curr += s
        if s > 0:
            pos += 1
        res.append(curr // pos if pos > 0 else 0)
    return res

def count_zero_crossings(moves):
    curr = 0
    last_sign = 0
    crossings = 0
    for m in moves:
        curr += m
        if curr > 0:
            if last_sign < 0:
                crossings += 1
            last_sign = 1
        elif curr < 0:
            if last_sign > 0:
                crossings += 1
            last_sign = -1
    return crossings

def latest_minimal_positive_charge(drains):
    curr = 0
    best_val = None
    best_idx = None
    for i, d in enumerate(drains):
        curr += d
        if curr >= 0:
            if best_val is None or curr <= best_val:
                best_val = curr
                best_idx = i
    return best_idx

def resetting_crate_totals(crates):
    res = []
    curr = 0
    for c in crates:
        curr += c
        if curr < c:
            curr = 0
        res.append(curr)
    return tuple(res)

def count_shelf_codes(letters):
    from itertools import permutations
    valid = set()
    for p in permutations(letters, 3):
        if p[0] != p[1] and p[1] != p[2]:
            valid.add("".join(p))
    return len(valid)

def playlist_pairs(lengths, target):
    res = set()
    for i in range(len(lengths)):
        for j in range(i + 1, len(lengths)):
            if lengths[i] + lengths[j] == target:
                a, b = lengths[i], lengths[j]
                res.add((min(a, b), max(a, b)))
    return sorted(list(res))

def unique_coin_sums(coins):
    from itertools import combinations
    sums = set()
    for r in (1, 2, 3):
        for c in combinations(coins, r):
            sums.add(sum(c))
    return sorted(list(sums))

def cheapest_seat_group(prices, k):
    if k < 0 or k > len(prices):
        return None
    return tuple(sorted(prices)[:k])

def divisible_box_subsets(weights, d):
    from itertools import combinations
    if d == 0:
        return 0
    count = 0
    for r in range(1, len(weights) + 1):
        for c in combinations(weights, r):
            if sum(c) % d == 0:
                count += 1
    return count

def two_digit_tickets(digits):
    from itertools import permutations
    res = set()
    for a, b in permutations(digits, 2):
        if a > 0 and 0 <= b <= 9:
            res.add(a * 10 + b)
    return sorted(list(res))

def count_team_splits(n, a, b):
    from math import comb
    if a <= 0 or b <= 0 or a + b != n:
        return 0
    ways = comb(n, a)
    return ways // 2 if a == b else ways

def invert_sensor_bits(readings, k):
    mask = (1 << k) - 1 if k > 0 else 0
    return tuple(r ^ mask for r in readings)

def first_single_bit_change(initial, states):
    for i, s in enumerate(states):
        diff = initial ^ s
        if diff > 0 and (diff & (diff - 1)) == 0:
            return i
    return -1

def group_badges_by_lowbit(badges):
    groups = {}
    for b in badges:
        if b > 0:
            low = b & -b
            groups.setdefault(low, []).append(b)
    return [sorted(groups[k]) for k in sorted(groups)]

def merge_permission_masks(masks, forbidden):
    res = 0
    for m in masks:
        res |= m
    return res & ~forbidden

def missing_xor_flag(items):
    xors = {items[i] ^ items[j] for i in range(len(items)) for j in range(i + 1, len(items))}
    v = 0
    while v in xors:
        v += 1
    return v

def find_last_sensor_dip(readings):
    for i in range(len(readings) - 2, 0, -1):
        if readings[i] < readings[i - 1] and readings[i] < readings[i + 1]:
            return i
    return -1

def closest_shelf_label(labels, target):
    if not labels:
        return None
    best = labels[0]
    for x in labels:
        if abs(x - target) <= abs(best - target):
            best = x
    return best

def first_available_seat(taken_seats):
    taken = set(taken_seats)
    seat = 1
    while seat in taken:
        seat += 1
    return seat

def second_lowest_unique_bid(bids):
    unique = sorted([b for b in set(bids) if bids.count(b) == 1])
    return unique[1] if len(unique) >= 2 else None

def locate_crate_weight(grid, target):
    for r in range(len(grid) - 1, -1, -1):
        for c in range(len(grid[r]) - 1, -1, -1):
            if grid[r][c] == target:
                return (r, c)
    return None

def find_separated_duplicate_tickets(codes):
    first_seen = {}
    res = set()
    for i, c in enumerate(codes):
        if c in first_seen:
            if i - first_seen[c] > 1:
                res.add(c)
        else:
            first_seen[c] = i
    return sorted(res)

def first_over_threshold_index(transactions, threshold):
    total = 0
    for i, t in enumerate(transactions):
        total += t
        if total > threshold:
            return i
    return -1

def highest_step_multiple(elevations, step):
    if step == 0:
        return 0 if 0 in elevations else None
    valid = [e for e in elevations if e % step == 0]
    return max(valid) if valid else None

def find_delivery_window(windows, timestamp):
    for start, end in windows:
        if start <= timestamp <= end:
            return (start, end)
    return (-1, -1)

def extract_aisles(labels):
    aisles = set()
    for label in labels:
        parts = label.split('-')
        if len(parts) == 2 and parts[0].isalpha() and parts[1]:
            aisles.add(parts[0])
    return tuple(sorted(aisles))

def best_seat_block(seat_map):
    best_start, best_len, cur_start, cur_len = -1, 0, -1, 0
    for i, ch in enumerate(seat_map):
        if ch == '.':
            if cur_len == 0: cur_start = i
            cur_len += 1
            if cur_len > best_len: best_len, best_start = cur_len, cur_start
        else:
            cur_len = 0
    return (best_start, best_len)

def playlist_minutes(tracks):
    total_sec = 0
    for t in tracks:
        if ':' in t:
            m, s = t.split(':', 1)
            if m.isdigit() and s.isdigit() and len(s) == 2 and int(s) < 60:
                total_sec += int(m) * 60 + int(s)
    return total_sec // 60

def dominant_ticket_char(code):
    filtered = [c for c in code if not c.isdigit()]
    if not filtered:
        return ''
    return max(filtered, key=lambda c: filtered.count(c))

def clean_firmware_version(ver):
    if not ver:
        return None
    parts = ver.split('.')
    if not all(p.isdigit() for p in parts):
        return None
    return '.'.join(str(int(p)) for p in parts)

def decode_crate_manifest(manifest):
    if not manifest: return ''
    res, num = [], ''
    for ch in manifest:
        if ch.isdigit(): num += ch
        elif ch.isalpha():
            if not num or int(num) == 0 or num.startswith('0'): return None
            res.append(ch * int(num)); num = ''
        else: return None
    return ''.join(res) if not num else None

def ledger_balance(ledger):
    if not ledger or not ledger.strip():
        return 0
    total = 0
    for token in ledger.split():
        if len(token) < 2 or token[0] not in '+-' or not token[1:].isdigit():
            return None
        total += int(token)
    return total

def shifted_workdays(shifts, offset, w):
    if not shifts:
        return ()
    return tuple(sorted({(s - 1 + offset) % w + 1 for s in shifts}))

def peak_sales_month(lengths, sales):
    if not lengths or not sales:
        return None
    best_m, best_s, idx = 1, None, 0
    for m, l in enumerate(lengths, 1):
        tot = sum(sales[idx:idx + l])
        if best_s is None or tot > best_s:
            best_m, best_s = m, tot
        idx += l
    return best_m

def watering_overlap(a, b, c, d):
    s, e = max(a, c), min(b, d)
    return (s, e) if s <= e else None

def free_cycle_days(scheduled, p):
    if p <= 0:
        return []
    busy = {d % p for d in scheduled}
    return [d for d in range(p) if d not in busy]

def days_until_expiry(current_day, anchor_day, k):
    if k <= 0:
        return None
    return (anchor_day - current_day) % k

def merge_festival_spans(spans):
    res = []
    for s, e in sorted(spans):
        if res and s <= res[-1][1] + 1:
            res[-1] = (res[-1][0], max(res[-1][1], e))
        else:
            res.append((s, e))
    return res

def latest_sunny_streak(gains):
    best_s, best_l, cur_s, cur_l = None, 0, 0, 0
    for i, g in enumerate(gains):
        if g > 0:
            if cur_l == 0:
                cur_s = i
            cur_l += 1
            if cur_l >= best_l:
                best_s, best_l = cur_s, cur_l
        else:
            cur_l = 0
    return (best_s, best_l)

def average_placard_word_length(placard):
    words = ["".join(c for c in w if c.isalnum()) for w in placard.split()]
    words = [w for w in words if w]
    if not words:
        return 0.0
    return round(sum(len(w) for w in words) / len(words), 2)

def count_letter_heavy_tickets(tickets):
    count = 0
    for t in tickets:
        upper = sum(1 for c in t if c.isupper())
        digits = sum(1 for c in t if c.isdecimal())
        if upper > digits:
            count += 1
    return count

def longest_seat_run(seat_map):
    filtered = seat_map.replace(" ", "")
    if not filtered:
        return 0
    max_run = cur = 1
    for a, b in zip(filtered, filtered[1:]):
        cur = cur + 1 if a == b else 1
        if cur > max_run:
            max_run = cur
    return max_run

def stanza_word_bounds(stanza):
    counts = [len(line.split()) for line in stanza.splitlines() if line.strip()]
    if not counts:
        return (0, 0)
    return (min(counts), max(counts))

def serial_digit_density(log):
    chars = [c for c in log if not c.isspace()]
    if not chars:
        return 0.0
    digits = sum(1 for c in chars if c.isdecimal())
    return round(digits / len(chars), 3)

def shortest_last_telegraph_token(msg):
    tokens = msg.split()
    if not tokens:
        return None
    min_len = min(len(t) for t in tokens)
    return [t for t in tokens if len(t) == min_len][-1]

import re

def sum_sensor_integers(status):
    return sum(int(x) for x in re.findall(r"-?\d+", status))

def rank_recipe_words(note):
    words = ["".join(c for c in w.lower() if c.isalpha()) for w in note.split()]
    words = [w for w in words if w]
    counts = {w: words.count(w) for w in set(words)}
    return sorted(counts, key=lambda w: (-counts[w], w))

def group_shelf_labels(labels):
    res = []
    for x in sorted(labels):
        if res and res[-1][1] + 1 == x:
            res[-1] = (res[-1][0], x)
        else:
            res.append((x, x))
    return res

def widest_furnace_cooldown(shifts):
    s = sorted(shifts)
    gaps = [(s[i][1], s[i+1][0]) for i in range(len(s) - 1) if s[i+1][0] > s[i][1]]
    return max(gaps, key=lambda g: (g[1] - g[0], g[0]), default=None)

def clip_sensor_windows(windows, min_v, max_v):
    clipped = set()
    for lo, hi in windows:
        c_lo, c_hi = max(lo, min_v), min(hi, max_v)
        if c_lo <= c_hi and lo <= hi:
            clipped.add((c_lo, c_hi))
    return sorted(clipped)

def busiest_ticket_tier(tiers, codes):
    if not tiers:
        return None
    def key(t):
        lo, hi = t
        cnt = sum(1 for c in codes if lo <= c <= hi)
        return (cnt, -(hi - lo), -lo)
    return tuple(max(tiers, key=key))

def unmuted_playlist_parts(segments, mute_start, mute_end):
    res = []
    for s, e in segments:
        if mute_start >= mute_end or e <= mute_start or s >= mute_end:
            if s < e: res.append((s, e))
        else:
            if s < mute_start: res.append((s, mute_start))
            if mute_end < e: res.append((mute_end, e))
    return sorted(res)

def common_seat_block(blocks):
    if not blocks:
        return None
    lo = max(b[0] for b in blocks)
    hi = min(b[1] for b in blocks)
    return (lo, hi) if lo <= hi else None

def solo_altitude_count(zones):
    counts = {}
    for lo, hi in zones:
        for a in range(lo, hi + 1):
            counts[a] = counts.get(a, 0) + 1
    return sum(1 for c in counts.values() if c == 1)

def subdivide_tide_window(start, end, k):
    if k <= 0 or start > end:
        return []
    w = (end - start) / k
    return [(float(start + i * w), float(start + (i + 1) * w)) if i < k - 1 else (float(start + i * w), float(end)) for i in range(k)]

def nested_price_brackets(brackets):
    res = []
    for a, b in brackets:
        if any(c <= a and b <= d and (c < a or b < d) for c, d in brackets):
            res.append((a, b))
    return sorted(res)

def shift_and_merge_slots(slots, offset):
    res = []
    for s, e in sorted((s + offset, e + offset) for s, e in slots):
        if res and s <= res[-1][1]:
            res[-1] = (res[-1][0], max(res[-1][1], e))
        else:
            res.append((s, e))
    return res

def find_last_shelf(labels, target):
    if not target:
        return -1
    t = target.lower()
    for i in range(len(labels) - 1, -1, -1):
        if t in labels[i].lower():
            return i
    return -1

def closest_sensor_reading(readings, ref):
    if not readings:
        return None
    best = readings[0]
    for r in readings[1:]:
        if abs(r - ref) <= abs(best - ref):
            best = r
    return best

def repeated_long_songs(durations, min_len):
    counts = {}
    for d in durations:
        if d > min_len:
            counts[d] = counts.get(d, 0) + 1
    return tuple(sorted(d for d, c in counts.items() if c >= 2))

def find_quiet_seat(grid):
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 0:
                left = row[c - 1] if c > 0 else 0
                right = row[c + 1] if c + 1 < len(row) else 0
                if left != 1 and right != 1:
                    return (r, c)
    return None

def second_lowest_positive_price(prices):
    pos = sorted({p for p in prices if p > 0})
    return pos[1] if len(pos) >= 2 else None

def first_strict_peak(altitudes):
    for i in range(1, len(altitudes) - 1):
        if altitudes[i] > altitudes[i - 1] and altitudes[i] > altitudes[i + 1]:
            return i
    return -1

def first_dominant_crate(weights):
    total = 0
    for w in weights:
        if w > total:
            return w
        total += w
    return None

def longest_unique_room_code(codes):
    best = ""
    for code in codes:
        if len(set(code)) == len(code) and len(code) > len(best):
            best = code
    return best

def rug_areas(pegs):
    areas = set()
    n = len(pegs)
    for i in range(n):
        for j in range(i + 1, n):
            area = abs(pegs[i][0] - pegs[j][0]) * abs(pegs[i][1] - pegs[j][1])
            if area > 0:
                areas.add(area)
    return sorted(areas)

def is_orthogonal_flight(pts):
    if len(pts) < 3:
        return False
    vecs = [(pts[i+1][0] - pts[i][0], pts[i+1][1] - pts[i][1]) for i in range(len(pts) - 1)]
    if any(v == (0, 0) for v in vecs):
        return False
    return all(v1[0]*v2[0] + v1[1]*v2[1] == 0 for v1, v2 in zip(vecs, vecs[1:]))

def double_pasture_area(pts):
    if len(pts) < 3:
        return 0
    total = 0
    for i in range(len(pts)):
        x1, y1 = pts[i]
        x2, y2 = pts[(i + 1) % len(pts)]
        total += x1 * y2 - x2 * y1
    return abs(total)

def min_poster_frame(photos):
    if not photos:
        return (0, 0)
    norm = [(min(w, h), max(w, h)) for w, h in photos]
    return (max(w for w, h in norm), max(h for w, h in norm))

def seat_squared_distances(stage, seats):
    sx, sy = stage
    dists = {(x - sx)**2 + (y - sy)**2 for x, y in seats}
    dists.discard(0)
    return sorted(dists)

def valid_shelf_codes(digits):
    res = set()
    n = len(digits)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if digits[j] < digits[i] and digits[j] < digits[k]:
                    res.add(digits[i] + digits[j] + digits[k])
    return sorted(res)

def playlist_duration_pairs(durations, target):
    seen = set()
    pairs = set()
    for d in durations:
        if target - d in seen:
            pairs.add((min(d, target - d), max(d, target - d)))
        seen.add(d)
    return sorted(pairs)

def count_sparse_seat_maps(n):
    if n <= 0:
        return 0
    a, b = 1, 2
    for _ in range(n - 1):
        a, b = b, a + b
    return b - 1

def heaviest_crate_tuple(weights, k):
    unique_w = sorted(set(weights))
    if k < 0 or k > len(unique_w):
        return None
    if k == 0:
        return ()
    return tuple(unique_w[-k:])

def positive_three_step_walks(steps):
    unique_steps = set(steps)
    count = 0
    for s1 in unique_steps:
        for s2 in unique_steps:
            for s3 in unique_steps:
                if s1 + s2 + s3 > 0:
                    count += 1
    return count

def count_coin_piles(n, k, m):
    if k < 0 or (k == 0 and n != 0):
        return 0
    if k == 0 and n == 0:
        return 1
    rem = n - k * m
    if rem < 0:
        return 0
    res = 1
    for i in range(1, k):
        res = res * (rem + i) // i
    return res

def generate_badge_codes(a, b):
    codes = {c1 + c2 for c1 in a for c2 in b if c1 != c2}
    return sorted(codes)

def balanced_signal_sublists(signals):
    count = 0
    n = len(signals)
    for i in range(n):
        pos = neg = 0
        for j in range(i, n):
            if signals[j] > 0: pos += 1
            elif signals[j] < 0: neg += 1
            if pos == neg: count += 1
    return count

def count_close_price_pairs(prices, d):
    if d < 0:
        return 0
    n = len(prices)
    return sum(1 for i in range(n) for j in range(i + 1, n) if abs(prices[i] - prices[j]) <= d)

def find_shelf_pairs(weights, target):
    n = len(weights)
    res = []
    for i in range(n):
        for j in range(i + 1, n):
            if weights[i] + weights[j] == target:
                res.append((i, j))
    return res if res else None

def count_spaced_seats(n, k):
    if k == 0:
        return 1
    if n <= 0 or k < 0 or k > (n + 1) // 2:
        return 0
    from math import comb
    return comb(n - k + 1, k)

def best_playlist_tuple(durations, k, target):
    from itertools import combinations
    if k < 0 or k > len(durations):
        return None
    combos = [tuple(sorted(c)) for c in combinations(durations, k)]
    return min(combos, key=lambda c: (abs(sum(c) - target), c))

def gear_gap_spectrum(gears):
    n = len(gears)
    diffs = set()
    for i in range(n):
        for j in range(i + 1, n):
            diffs.add(abs(gears[i] - gears[j]))
    return sorted(diffs)

def valid_tile_orders(tiles):
    from itertools import permutations
    res = set()
    for p in permutations(tiles):
        if all(not (p[i] % 2 == 0 and p[i+1] % 2 == 0) for i in range(len(p) - 1)):
            res.add(p)
    return sorted(res)
